-- GENERATED by `wfj generate` from data/quest/quest-0093.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [93016] = { "Una breve lezione di storia", "Parla con Mordent Vesprombroso a Shen'dralas per avere informazioni sui cristalli che hai riparato.", "Dovrai perdonarmi se ti ho mandato a svolgere una serie di compiti senza fornirti alcun contesto. Non avevo considerato quanto potesse sembrare sospetto, soprattutto ora che i cieli hanno assunto un aspetto così drammatico.\n\nRisponderò volentieri alle tue domande.", nil, "Spero che questa spiegazione abbia dissipato ogni dubbio, {name}. Come vedi, non agivo con cattive intenzioni, e se non ti ho spiegato tutto a fondo fin dall'inizio è stato solo per l'entusiasmo di avere la possibilità di veder brillare di nuovo le luci dei cristalli.\n\nNon vedo l'ora di visitare di nuovo il tempio di Shen'dralas, anche se potrebbe volerci del tempo prima che trovi il coraggio di parlare con gli Shen'dralar che vi dimorano.\n\nTu, invece...", 0xd302b652, 0x5b6ead89, 0x2a2142fc, nil, 0x8c911484, "...m." },
  [93030] = { "Il cavaliere del lutto", "Parla con il cavaliere del lutto per saperne di più sulla sua missione incompiuta.", "Un tempo ero un cavaliere come te, legato al servizio della luce. Poi sono morto. A quanto pare abbiamo questo in comune.\n\nA differenza di te, però, io sono legato a questo luogo da uno scopo incompiuto, da un giuramento non mantenuto. Se vuoi ascoltare, ti racconterò della mia ricerca... e del mio fallimento.", nil, nil, 0xa9e3fad4, 0x8973b7c9, 0x7f0121b3, nil, nil, "...mm" },
  [93034] = { "La ⟦Valley of Bones=Valle delle Ossa⟧", "Migliora la tua reputazione presso i Gelkis e trova Nerlokh vicino alla ⟦Valley of Bones=Valle delle Ossa⟧, molto a est del ⟦Gelkis Village=Villaggio dei Gelkis⟧.", "Mentre eri via, uno dei nostri esploratori è tornato al villaggio con notizie che hanno confermato i miei timori.\n\nI Magram stanno tramando qualcosa, {name}. E non è niente di buono.\n\nLa ⟦Valley of Bones=Valle delle Ossa⟧, molto a est, è una terra maledetta in cui pochi centauri hanno osato entrare, e ancora meno ne sono tornati. Il nostro nemico vi ha trovato qualcosa, qualcosa di malvagio, e dobbiamo scoprire di cosa si tratta.\n\nCerca l'esploratore Nerlokh all'ingresso meridionale, ma forse dovrai dimostrare ancora il tuo valore ai Gelkis.", nil, nil, 0x1c23f49e, 0xc34a0910, 0xad8eaac4, nil, nil, "...mm" },
  [93035] = { "Devastare i devastatori", "Mantieni la tua reputazione presso i Gelkis e uccidi $N1 Undead Ravager, poi torna da Nerlokh all'ingresso meridionale della ⟦Valley of Bones=Valle delle Ossa⟧.", "Non serve guardare lontano per vedere i non morti che si trascinano davanti a noi, ma hai notato qualcosa di strano in loro?\n\nCamminano su due gambe, non su quattro! Questi scheletri non sono nemmeno i nostri congiunti caduti. I Magram devono profanare i corpi di chi è morto molto prima che ⟦Desolace=Desolanda⟧ fosse il nostro dominio. Non riesco a immaginare come abbiano giustificato il voltare le spalle a Madre Theradras e il dissacrare cadaveri che riposano qui da secoli.\n\nDai pace ai non morti, {name}.", nil, nil, 0x153e1e0b, 0x5480b72b, 0x3fc928fd, nil, nil, "...mm" },
  [93036] = { "Infiltrarsi nel culto", "Parla con ⟦Sania Silverstream=Sania Vena d'Argento⟧ al ⟦Shen'dar Village=Villaggio di Shen'dar⟧.", "Forse lo sai, forse no, ma ⟦Sania Silverstream=Sania Vena d'Argento⟧, laggiù, è una \"missionaria\" degli Al'Aketh. A loro piace fingersi un normale ordine religioso e mandano in giro emissari inoffensivi a reclutare. Finora abbiamo tollerato Sania per evitare uno scontro diretto con il culto, ma è chiaro che l'illusione della pace non durerà ancora a lungo.\n\nSei <nuovo/nuova> di qui e quasi nessuno ti conosce, quindi vorrei vedere se riesci a usare Sania per avvicinarti al culto e scoprire che piani hanno per il villaggio.", nil, "Salute, <figlio/figlia>, il mio nome è ⟦Sania Silverstream=Sania Vena d'Argento⟧ e sono una sacerdotessa novizia dell'Ordine degli Al'Aketh. Vuoi saperne di più sul nostro sovrano, il Signore del Vento Al'Akir?\n\nAlla tavola del Signore del Vento c'è sempre posto per i giusti e per i pentiti.", 0xbb1fd4b2, 0x82bd3020, 0x59a588f5, nil, 0x23ca2220, "...m." },
  [93037] = { "Smascherare gli esiliati", "Mantieni la tua reputazione presso i Gelkis e porta $N1 ⟦Necromantic Garb=Abiti Negromantici⟧ a Nerlokh, all'ingresso della ⟦Valley of Bones=Valle delle Ossa⟧.", "Mentre aspettavo il tuo arrivo, ho guardato un po' più in là, tra gli archi, e ho notato qualcosa che ho bisogno che tu mi confermi.\n\nNon sopporto di dirlo ad alta voce. Non finché i miei sospetti non saranno provati.\n\n{name}, mentre prendi confidenza con la valle, uccidi alcuni dei negromanti che sembrano più deboli degli altri. Strappa loro le vesti rituali, con cura, e portamele. Devo sapere se la mia mente e la mia vista sono lucide.", nil, nil, 0x7c82b69a, 0xffce3927, 0x80ee307a, nil, nil, "...mm" },
  [93041] = { "Affrontare la verità", "Mantieni la tua reputazione presso i Gelkis e porta un ⟦Accursed Skull=Teschio Maledetto⟧ e gli ⟦Gelkis Necromantic Garb=Abiti Negromantici dei Gelkis⟧ a Uthek la Saggia al ⟦Gelkis Village=Villaggio dei Gelkis⟧.", "Questa scoperta è devastante per il nostro clan, ma è nel nostro interesse che la conosca solo chi deve saperla. Uthek è una di queste persone: deve essere al corrente di ciò che succede qui. Credo che saprà come procedere.\n\nPorta questa e mostragliela. Per sicurezza dovremmo portarle anche una prova della negromanzia stessa. Trova un teschio che sembri maledetto da poco. Sospetto che li ammassino tra le fauci di uno degli scheletri dei giganti.", nil, nil, 0x8463c2a2, 0x5ff29d36, 0x49b8d0dc, nil, nil, "...mm" },
  [93044] = { "Un grido purificatore", "Mantieni la tua reputazione presso i Gelkis e porta le Tears of Theradras a Uthek la Saggia al ⟦Gelkis Village=Villaggio dei Gelkis⟧.", "Quando tornerai da Nerlokh nella ⟦Valley of Bones=Valle delle Ossa⟧, non sarà a mani vuote.\n\nEntra nella grotta nel cuore del nostro villaggio e cerca Mulara. Chiedile le lacrime di Theradras a nome mio. Le nostre scorte sono scarse, ma sono la nostra migliore speranza contro l'immonda negromanzia dei Magram!\n\nIo preparerò un rituale. Creeremo un'arma per spezzare i loro incantesimi.", nil, nil, 0x0d21377b, 0xf97c47c3, 0x548749f1, nil, nil, "...mm" },
  [93045] = { "Metti alla prova la tua teoria", "Mantieni la tua reputazione presso i Gelkis e dissolvi la maledizione negromantica che grava sul ⟦Accursed Skull=Teschio Maledetto⟧. Quando ci sarai riuscit<o/a>, torna a fare rapporto a Nerlokh vicino alla ⟦Valley of Bones=Valle delle Ossa⟧.", "Ho messo il teschio che mi hai dato accanto a varie ossa che ho trovato mentre aspettavo il tuo ritorno. Subito ho visto una luce malsana diffondersi dal teschio e fare sue quelle vecchie ossa. Ora capisco perché il richiamo della negromanzia sia così difficile da resistere.\n\nTi ricordi di questo cristallo? È draenetista. Ne conosco poco le potenzialità, ma credo che possa incanalare il potere di Theradras. Con esso, forse potrai dissolvere la maledizione.\n\nIl luogo del rituale si trova vicino allo stagno, appena a est del villaggio.", nil, nil, 0xdd0047fc, 0x79d5c999, 0x89f01149, nil, nil, "...mm" },
  [93058] = { "Salvare i nostri", "Mantieni la tua reputazione presso i Gelkis e libera $N1 Gelkis Captive nella ⟦Valley of Bones=Valle delle Ossa⟧. Quando hai finito, torna da Nerlokh vicino all'ingresso.", "C'è stata una breve battaglia tra alcuni negromanti, appena dietro la collina, e ne ho approfittato per dare un'occhiata più da vicino all'interno.\n\n{name}, non tutte le nostre perdite recenti erano disertori. Ci sono dei Gelkis tenuti prigionieri più avanti nella valle! Non ho potuto indagare sulla loro situazione perché un enorme bruto dei Magram ha iniziato a caricare verso di me. Mi ritengo fortunato che abbia perso interesse in fretta.\n\nDevi tornare nella ⟦Valley of Bones=Valle delle Ossa⟧ e liberarli. I Gelkis restano uniti.", nil, nil, 0x76503b38, 0x148d8d61, 0x52532c02, nil, nil, "...mm" },
  [93062] = { "Seppellire le ossa", "Mantieni la tua reputazione presso i Gelkis e dissolvi le maledizioni di $N1 evocazioni fallite in tutta la ⟦Valley of Bones=Valle delle Ossa⟧.", "A proposito di questo tuo bastone. Lo riconosco, è uno di quelli di Uthek, e hai detto che è stato costruito con le lacrime di Theradras, potenziato con un ⟦Draenethyst Crystal=Cristallo di Draenetista⟧, e che può dissolvere la magia oscura?\n\nHo notato che ci sono scheletri bloccati appena sotto il terreno roccioso, più avanti nella valle. Credo che siano evocazioni fallite dei negromanti esiliati, condannate forse per sempre a un'esistenza soffocata nella terra.\n\nRiportarli al riposo gioverebbe alla nostra causa, e ai loro spiriti.", nil, nil, 0x25960f2c, 0x00d4e816, 0x21e3a666, nil, nil, "...mm" },
  [93065] = { "Prepararsi alla battaglia", "Parla con Valennia Stormfist nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧.", "I Pacificatori si stanno mobilitando e ci stiamo tutti preparando a partire. Fai tutti i preparativi che ti servono e raggiungici sulla strada orientale che porta a nord, fuori dal paese. Faremo un ultimo controllo con tutti prima di metterci in marcia.", nil, "Siamo pronti più che mai.", 0x5db1f556, 0xd94373fd, 0x8619e90a, nil, 0xda1d39ff, "...m." },
  [93066] = { "Il rifugio dei ⟦Bristleback=Mantotergo⟧", "Mantieni la tua reputazione presso i Magram e uccidi i verrospini al rifugio dei ⟦Bristleback=Mantotergo⟧. Poi fai rapporto a Hagiak al ⟦Magram Front=Fronte Magram⟧, dall'altra parte della ⟦Valley of Bones=Valle delle Ossa⟧, a ⟦Desolace=Desolanda⟧.", "Dall'altra parte della valle abbiamo stabilito un piccolo avamposto per prepararci a marciare nella foresta vicina. Prima di andare dritt<o/a> laggiù, voglio che ti occupi di una recente incursione dei ⟦Bristleback=Mantotergo⟧ lungo la strada. Sembra che siano arrivati più o meno quando siamo arrivati noi, ma sono riusciti a impadronirsi di un manufatto del tempio vicino che ci ha tenuti a distanza.\n\nIl compito è semplice. Cerca le spine e i maiali. Uccidine un bel po', senza distinzione. Poi fai rapporto a Hagiak all'accampamento di cui ti ho parlato.", nil, "Mi dispiace che tu abbia fatto tutta questa strada, forestiero, ma non sei necessario al fronte dei Magram. Mi hai già distratto abbastanza da ritardare il nostro lavoro.\n\nTorna da Orgrul e digli--\n\nA pensarci bene, ho qualcosa per un soldato sacrificabile come te. Sarà rapido, nel bene e nel male.", 0x6802c038, 0x895f28cd, 0x20e4bcb9, nil, 0xefdb0f81, "...m." },
  [93072] = { "Soluzioni a lungo termine", "Mantieni la tua reputazione presso i Magram e uccidi $N1 Outcast Scout, $N2 Outcast Marauder e $N3 Outcast Necromancer, poi torna da Hagiak al ⟦Magram Front=Fronte Magram⟧.", "Qui fuori c'è un secondo villaggio di centauri, a sud-ovest. Quello appartiene ai Gelkis. Ti aspetti che ti mandi laggiù solo per versare un po' di sangue, giusto? Bene. Sarà meglio che sia il tuo primo pensiero, altrimenti metterei in dubbio la tua fedeltà ai Magram!\n\nCosa aspetti? Va'! Uccidi!", nil, "I miei esploratori hanno già riferito il tuo successo. Ora forse possiamo continuare il nostro addestramento in pace. I Gelkis devono imparare che questo luogo, e ⟦Desolace=Desolanda⟧, appartengono ai centauri nati dal sangue dei Magram.\n\nSe vedi dei ritardatari, tagliagli la testa. Dovrebbero avere paura di mettere zoccolo fuori dalla loro piccola topaia.\n\nAnche quella sarà nostra, un giorno non lontano.", 0xaf937461, 0x1208c910, 0xd1a41853, nil, 0x673c0dc0, "...m." },
  [93089] = { "Ciò che verrà", "Parla con Elaadrin Evengale quando sei pront<o/a> a lasciare l'⟦Zephras Isle=Isola di Zephras⟧.", "Ti prego, porta i miei ringraziamenti a Elaadrin per tutto ciò che l'Alto Ordine e i tuoi nuovi amici di questo \"Kirin Tor\" hanno fatto per l'⟦Zephras Isle=Isola di Zephras⟧. So che l'Alto Ordine intende lasciare l'isola, e il vostro ordine ha la mia benedizione e i miei auguri per questa spedizione.\n\nPosso solo sperare che qualunque soluzione arcana trovi l'Alto Ordine possa davvero darci la stabilità che ci è mancata in questi anni. Se intendi andare con loro... be', questa missione ne uscirà ancora più forte.\n\nChe i venti siano con te, {name}.", nil, "Mi rallegra sapere che abbiamo la benedizione dell'alto anziano Shadowsong per la nostra spedizione. Ora che il culto è stato sconfitto e i preparativi sono fatti, credo che sia finalmente giunto il momento.\n\nAnsirem ha lavorato con impegno per aiutarci ad avviare un trasporto stabile di skycutter tra la città di Dalaran e l'⟦Zephras Isle=Isola di Zephras⟧. Abbiamo fatto tutte le prove possibili, ed è giunto il momento che la nostra avanguardia parta.", 0x50a257df, 0xb2d66ffb, 0xa384a68c, nil, 0xd86a7736, "...m." },
  [93090] = { "Ciò che verrà", "Parla con Ayessa Cantalba quando sei pront<o/a> a lasciare l'⟦Zephras Isle=Isola di Zephras⟧.", "Ti prego, porta i miei ringraziamenti ad Ayessa per tutto ciò che i Plasmatori di Venti e i tuoi nuovi amici di questo \"Circolo della Terra\" hanno fatto per l'⟦Zephras Isle=Isola di Zephras⟧. So che c'è il piano di portare via dall'isola gli sciamani dei Plasmatori di Venti, e il vostro ordine ha la mia benedizione e i miei auguri per questa spedizione.\n\nPosso solo sperare che qualunque soluzione trovino i Plasmatori di Venti possa davvero darci la stabilità che ci è mancata in questi anni.\n\nChe i venti siano con te, {name}.", nil, "Sono lieta di sapere che abbiamo la benedizione dell'alto anziano Shadowsong per la nostra spedizione. Ora che il culto è stato sconfitto e i preparativi sono fatti, credo che sia finalmente giunto il momento.\n\nMuln ha lavorato con impegno per aiutarci ad avviare un trasporto stabile di skycutter tra l'⟦Zephras Isle=Isola di Zephras⟧ e un luogo chiamato Mulgore, dove ha sede il Circolo della Terra. Abbiamo fatto viaggi di prova e alcuni dei nostri aspettano già dall'altra parte.", 0x50a257df, 0x42ef0bb4, 0xfa29d4a6, nil, 0xeaba7e66, "...m." },
  [93122] = { "Dare un'occhiata in giro", "Mantieni la tua reputazione presso i Gelkis e indaga sui punti d'interesse dei centauri a Shen'dralas. Poi torna da Nerlokh, all'ingresso della ⟦Valley of Bones=Valle delle Ossa⟧, con ciò che hai scoperto.", "Abbiamo tutti sottovalutato la forza e la presenza del clan dei Magram in questa zona, ma potrebbe rivelarsi un vantaggio.\n\nCon tanti dei loro distratti, e con il loro rifiuto di accogliere gli esiliati degli altri clan, chi è rimasto a difendere il villaggio? E il loro Khan?\n\nHo bisogno che tu entri nella valle, più a fondo di quanto tu abbia mai fatto, e che ti guardi intorno. Se i Magram sono così ben fortificati qui come sembra, potrebbero aver lasciato scoperto il loro villaggio...", nil, nil, 0x9009cbea, 0x26ae294d, 0x1c056f62, nil, nil, "...mm" },
  [93125] = { "Tornare a casa", "Mantieni la tua reputazione presso i Gelkis e scorta Rokren fuori dall'Outcast Hideaway. Poi racconta a Nerlokh, vicino alla ⟦Valley of Bones=Valle delle Ossa⟧, cos'è successo.", "Tu! Ti ho vist<o/a> là fuori combattere gli esiliati. Non so da dove vieni, ma ho bisogno del tuo aiuto.\n\nSono stato attirato qui dai miei fratelli Gelkis con la promessa che sarei stato al sicuro. Sapevo che la guerra a ⟦Desolace=Desolanda⟧ ci stava sfuggendo di mano, ma non avrei mai immaginato che la mia stessa gente si sarebbe rivolta alla negromanzia in un contorto tentativo di passare al clan dei Magram. Quando mi sono opposto, hanno minacciato di uccidermi se avessi mai messo zoccolo fuori da questa tenda!\n\nTi prego, aiutami.", nil, nil, 0xf193b151, 0x86ad2352, 0x15267230, nil, nil, "...mm" },
  [93127] = { "Sentinelle della vetta", "Riattiva le pietre sentinella a nord, a ovest e a sud intorno ai cultisti di Spinanera.", "Il Re Selvatico può avere il vantaggio numerico, ma possiamo superarlo in manovra con la tattica.\n\nPotenzia le nostre pietre sentinella viventi sulle colline circostanti: possono tracciare per noi i movimenti degli Spinanera. Le creste a nord, i pendii a sud e le alture a ovest hanno tutti pietre prosciugate che si attiveranno quando rileveranno la presenza dei tuoi alleati.\n\nProcedi con cautela mentre lavori: le pattuglie degli Spinanera affollano questi sentieri, e la loro presenza è proprio il motivo per cui dobbiamo mettere questa terra sotto sorveglianza vigile.", nil, nil, 0xe616b857, 0x21d2e6f5, 0x0ded7b03, nil, nil, "...mm" },
  [93128] = { nil, "Mantieni la tua reputazione presso i Gelkis e uccidi Khan Jhen al Magram Village. Quando ci sarai riuscit<o/a>, fai rapporto a Uthek la Saggia al ⟦Gelkis Village=Villaggio dei Gelkis⟧, a ⟦Desolace=Desolanda⟧.", "Per quanto vorrei che fossero Uthek o Khan Shaka a dare l'ordine, temo che la nostra occasione sia breve. Troppo breve per consultare chi sta al ⟦Gelkis Village=Villaggio dei Gelkis⟧.\n\nCredo che, con ciò che sta accadendo qui nella ⟦Valley of Bones=Valle delle Ossa⟧, i Magram abbiano lasciato Khan Jehn con difese minime. Se mai c'è stato un momento per attaccare il Khan di un altro clan, è adesso.\n\nMa, {name}, con un Khan non si scherza, e meno che mai con Jehn. Se hai il coraggio di fare la tua mossa, devi essere rapid<o/a>, ma non sottovalutarlo.", nil, nil, 0x67d27eda, 0xe9180567, 0xe9fc8e6f, nil, nil, "e..mm" },
  [93129] = { "La minaccia della fame", "Mantieni la tua reputazione presso i Magram e riporta $N1 ⟦Stolen Supplies=Scorte Rubate⟧ a Hagiak al ⟦Magram Front=Fronte Magram⟧.", "Visto che sembri fin troppo ansios<o/a> di aiutare il nostro clan, sono sicuro che saresti dispost<o/a> a recuperare qualche provvista mentre sei all'Outcast Hideaway.\n\nAbbattere i nostri nemici dovrebbe bastare come motivazione per un Magram, ma non vedo perché non potremmo trarne anche un profitto.\n\nQuando avremo sistemato gli esiliati, potremo assicurare questo posto ai Magram e radunare un esercito per mettere in ginocchio gli altri clan!", "Massacra i loro soldati e fa' morire di fame i sopravvissuti. Il loro piccolo nascondiglio non dovrà mai più essere una base sufficiente contro il nostro clan!", "<Hagiak sbircia in diverse casse senza dire una parola all'inizio.>\n\nDi tutte le cose da portare in prima linea, non mi sarei mai aspettato... lasciamo stare. Alcune di queste casse contengono cibo, e questo è ciò che conta. Abbiamo accorciato notevolmente il tempo che possono sopravvivere qui.\n\nLa vittoria finale per il nostro clan si avvicina.", 0x73784842, 0xa76555fc, 0xd084fd3d, 0xf4c9a3fb, 0x3ee1d052, "....." },
  [93159] = { "Lo strano eremita", "Parla con lo Strange Hermit nella ⟦Shadowgale Forest=Foresta di Ventombra⟧ e scopri di più su di lui.", "Ehm, uhm... c-ciao, cioè, volevo dire, salve! Anzi, saluti! Scusa... è, uhm, passato così tanto tempo dall'ultima volta che ho parlato davvero con un'altra persona. Temo di essere un po' arrugginito.\n\n<La strana figura incappucciata si agita a disagio davanti a te.>\n\nAllora, ehm, uhm... come va la tua giornata?", nil, "...questo è più o meno tutto quello che ho da dire in proposito. Ero... uhm... da qualche altra parte prima di essere qui. Ora sono qui e ho i miei amici e le mie cose. C-cose che ho costruito, intendo. È più o meno tutto ciò di cui ho bisogno. Credo che sia tutto ciò di cui ho bisogno, comunque.\n\nDevo dire, però, che è bello parlare con qualcuno che risponde. Gli spiriti della foresta ci provano, ma finiscono sempre per cantarmi addosso. È bello a modo suo, ma non è proprio una conversazione s-stimolante.", 0xc281d56b, 0x91510117, 0x813fe37d, nil, 0xf694abb5, "...m." },
  [93160] = { "I doni della foresta", "Raccogli $N1 Shadowgale Acorn nella ⟦Shadowgale Forest=Foresta di Ventombra⟧.", "Mi fa davvero piacere che tu sia passat<o/a> a parlare con me! S-se vuoi darmi una mano, mi servirebbe un po' d'aiuto a raccogliere le ghiande dal suolo della foresta. Ho già raccolto quasi tutte quelle qui vicino, ma nella foresta ci sono davvero tanti di quei cosi a metà tra raptor e uccelli. Là fuori è pericoloso e preferirei non diventare il pranzo di un uccello gigante!\n\nQuindi, se vuoi, magari potresti raccoglierle tu per me? Se lo fai, preparerò qualcosa di buono per tutti e due!", "Mmm, credo che ti piacerà quello che riesco a cucinare con queste ghiande!", "Grazie, <straniero/straniera>! Vedrai che sono deliziose, una volta arrostite!\n\nScusami, non ci metterò molto a prepararle.", 0x4aa75777, 0x076dacd0, 0xb98c76cc, 0xd9fab18b, 0xc1c8b911, "....." },
  [93161] = { "L'Elsa Antica", "Trova qualcuno che sia interessato all'Elsa Antica che hai trovato tra le rovine di Ban'aethal.", "Nella debole luce della tua torcia, noti un piccolo luccichio di metallo. A un'ispezione più attenta, è chiaro che si tratta dell'elsa spezzata di un'antica spada.\n\nPur priva di lama, si vede chiaramente che quest'elsa è frutto di una lavorazione magistrale. È un prezioso cimelio e potrebbe esserci chi è interessato a saperne di più.", "Aspetta... cos'è quello che hai lì? Possibile?", "Questo oggetto ha per la mia gente un valore che va oltre ogni parola. Questa spada è stata forgiata dal leggendario fabbro magico Luminarian.\n\nLuminarian accompagnò la nostra gente quando fuggimmo da Kalimdor e proseguì il suo lavoro nelle Isole Celesti per secoli. Molte delle armi e armature che vedi impugnate oggi su Zephras sono realizzate nello stile del suo incredibile lavoro.\n\nLa lama è spezzata e la sua magia esaurita, ma non è irrecuperabile. Prendila. Trova qualcuno che conosca meglio le opere di Luminarian. Forse potrà aiutarti.", 0x6be8180e, 0x4a6d29a7, 0x44c924e0, 0xbcee243f, 0x033efc5a, "....." },
  [93162] = { "Testa del Disintegratore", nil, "Ti sei certamente dimostrat<o/a> degn<o/a> ai miei occhi, {name}, ma gli altri della mia tribù sono meno facili da convincere. Per questo dovrai continuare i tuoi sforzi contro i Legashi.\n\nPortami le corna dei satiri Legashi uccisi. Ogni fascio che mi porterai sarà un simbolo del tuo servizio agli Zannanera.", nil, nil, 0x5d215c20, nil, 0xb1c3b2ab, nil, nil, ".m.mm" },
  [93163] = { "Cuore del Disintegratore", "Porta il Cuore del Disintegratore al ⟦Thorium Point=Presidio del Torio⟧.", "Costruito e distrutto di nuovo; il cuore di Iodax il Disintegratore riposa nelle tue mani. Il golem era probabilmente un'invenzione dei nani Ferroscuro, o di qualcosa che li precedeva. Per questo, i nani del ⟦Thorium Point=Presidio del Torio⟧ potrebbero essere interessati alla tua scoperta qui.", nil, nil, 0xd743fc17, 0xb2f54aa1, 0xd8bbee31, nil, nil, "...mm" },
  [93165] = { "La pietà cade nel vuoto", "Raccogli $N1 Al'Aketh Cultist's Ear dai cultisti Al'Aketh nella ⟦Shadowgale Forest=Foresta di Ventombra⟧, al ⟦Shrine of Akir=Sacrario di Akir⟧ o nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧.", "Gli Al'Aketh hanno portato una grande tragedia sulla nostra enclave, e il sangue va ripagato con il sangue.\n\nHo un'offerta per te, <straniero/straniera>. Se ti trovi a scontrarti con questi cultisti maledetti, portami le orecchie di quelli che uccidi. Ti ricompenserò per ognuna che mi porterai, con denaro e, col tempo, con l'accesso ai segreti dei Nightclaw, se dimostrerai di essere un vero amico.", "Non avrò pace finché le mie zanne non avranno squarciato la gola di ogni singolo cultista di quest'isola.", "Ottimo lavoro. Eliminare il culto non può che portare del bene. Spero che questo faccia capire che con i Nightclaw non si scherza e che i nostri rancori sono profondi.\n\nCredo che ti aspetti un bel po' di lavoro, a combattere il culto. Se raccogli altre orecchie, portale qui.", 0x67167132, 0x29ccfeb1, 0xf3604d96, 0x3dfb4bed, 0x1c83ddb0, "....." },
  [93172] = { "Liberare gli Hollow", "Distruggi 10 Wind Hollow nella ⟦Shadowgale Forest=Foresta di Ventombra⟧.", "Quasi tutti gli elfi di quest'isola pensano che questi boschi siano infestati, e non hanno torto.\n\nAlle antiche rovine a nord-est si raduna uno strano tipo di spiriti simili a fantasmi. Certe notti si possono quasi sentire \"cantare\". Non somiglia a nessun canto che abbia mai sentito, ma è di sicuro un canto ed è... così triste.\n\nNon so perché, ma credo che lì, a un certo punto, sia successo qualcosa di terribile, e che gli spiriti ci siano rimasti intrappolati in qualche modo. Se te la senti, forse puoi aiutarli a liberarsi?", "Possiamo solo sperare che quei poveri spiriti riescano a trovare pace dopo essere stati liberati da questo luogo.", "Grazie, <straniero/straniera>.", 0x0e18dc30, 0x1267d2ac, 0xe5c300d2, 0xb1bfb39d, 0x66dd9c71, "....." },
  [93173] = { "(UNUSED) Il Rusty Gadget", "Riporta il ⟦Rusty Gadget=Congegno Arrugginito⟧ allo Strange Hermit nella ⟦Shadowgale Forest=Foresta di Ventombra⟧.", "<Mentre le correnti vorticose che tengono insieme il Wind Hollow cominciano a dissolversi, un piccolo congegno di metallo cade a terra ai tuoi piedi. Sembra una specie di aggeggio meccanico. Lo Strange Hermit ha detto che gli mancava ancora dell'attrezzatura. Potrebbe interessargli.>", nil, nil, 0xd8c783cf, 0x3216fc08, 0x02764b22, nil, nil, "...mm" },
  [93176] = { "I miei piccoli amici", "Usa gli oggetti contenuti nel ⟦Entomology Starter Kit=Kit Base di Entomologia⟧ per trovare e catturare un Arbor ⟦Tarantula=Tarantola⟧, un ⟦Hay Weevil Specimen=Esemplare di Punteruolo del Fieno⟧ e un Flesh Picker.", "Ammiri il mio piccolo serraglio, eh? È l'opera della mia non-vita. Ho passato ore e ore a studiarli: la loro anatomia, la loro dieta, perfino i loro rituali sociali.\n\nVuoi unirti a me in questo passatempo? Ecco, prendi questo pacco. Gli appunti e il materiale che contiene dovrebbero bastarti per cominciare. Se lo perdi, dovrai comprarne un altro da me per una piccola somma.", nil, nil, 0xd9137740, 0x98c50d57, 0xc04ef699, nil, nil, "...mm" },
  [93188] = { "Ritorno da Orgrul", "Mantieni la tua reputazione presso i Magram e torna a fare rapporto a Orgrul, vicino all'ingresso settentrionale della ⟦Valley of Bones=Valle delle Ossa⟧.", "Hai fatto abbastanza in prima linea. Possiamo cavarcela da soli.\n\nDi' a Orgrul che hai fatto la tua parte. Il ⟦Magram Front=Fronte Magram⟧ ora è più forte, e abbiamo messo gli occhi sull'accampamento degli esiliati come nostro prossimo insediamento, quando un'altra schiera di combattenti si unirà alla mischia.\n\nAllora? Muoviti!", nil, "Un fatto interessante si è verificato nel Magram Village durante la tua breve assenza. È stato un atto di guerra, eseguito con cura da un forestiero che combatte sotto la bandiera dei Gelkis.\n\nSe fosse accaduto qualche mese fa, avrei preteso l'esecuzione tua e di tutti gli altri forestieri che ignorantemente giocano agli inganni con i nostri clan.\n\nMa questa non è una circostanza ordinaria.\n\nÈ un'opportunità. Per te, per i Magram, per la guerra.", 0x14b1f8e5, 0x30764b3d, 0x99bb3d87, nil, 0x625db247, "...m." },
  [93196] = { nil, "Mantieni la tua reputazione presso i Magram e compi un rituale negromantico per resuscitare Khan Jehn. Il luogo del rituale si trova in una tenda presso il lago centrale del Magram Village.", "Il capo del nostro clan, Khan Jehn, è stato ucciso da una banda di stranieri molto simili a te. Agivano per conto del clan dei Gelkis.\n\nPuoi smettere di fingerti sorpres<o/a>. Un assalto al Magram Village mentre la nostra attenzione era altrove è una strategia di guerra prevedibile, soprattutto per i Gelkis.\n\nSai perché non mostro né rabbia né rimorso, <straniero/straniera>?\n\n<Orgrul ti porge un'arma familiare, intrisa di un potere ancora più grande dell'ultima volta che l'hai impugnata.>\n\nEcco perché.", nil, "I Gelkis reclutano forestieri per compiere subdole strategie di guerra, mentre il nostro clan li manderebbe a morire.\n\nEppure eccoti qui, {name}. Un forestiero che ha dimostrato feroce lealtà verso il clan Magram nonostante fosse così malvisto.\n\nNon conosco le tue motivazioni, ma riconosco di prima mano il tuo potenziale. Hai la mia gratitudine, e quella del nostro clan.\n\nPer noi non sei più un forestiero. Per noi, sei Magram.", 0x67d27eda, 0x571f4b9c, 0xc11d031e, nil, 0xeee43f3c, "e..m." },
  [93197] = { "Riparare le comunicazioni", "Porta i pacchi postali di Sebelia, dal campo sulla vetta del ⟦Mount Hyjal=Monte Hyjal⟧, alla locandiera Vizzie a ⟦Everlook=Lungavista⟧.", "Con tutti i combattimenti e la ritirata dal Padiglione di Nordrassil, siamo terribilmente a corto di personale qui fuori.\n\nSe fai la spola tra qui e ⟦Everlook=Lungavista⟧, ho della posta da portare in città per la distribuzione, e dobbiamo far salire tutta la posta in attesa. Ho una pila di pacchi pronti per il trasporto, se vuoi essere così gentile da aiutarci.", nil, nil, 0x03ce7777, 0xc50a4259, 0x444f3370, nil, nil, "...mm" },
  [93224] = { "Totem intagliati dei centauri", "Ottieni $N1 Carved Centaur Totem uccidendo centauri di qualsiasi clan in tutta ⟦Desolace=Desolanda⟧, poi portali al capitano Pentigast al ⟦Nijel's Point=Presidio di Nijel⟧.", "Probabilmente non ti sorprende che entrambi i clan di centauri siano restii ad accettare aiuto da chiunque non faccia parte del loro clan. Questo vale soprattutto per gente come te e me... sai, i non centauri.\n\nUna cosa che abbiamo tutti in comune è la consapevolezza che il denaro è potere, e abbiamo scoperto che i centauri del posto commerciano con legno intagliato. Se mi porti qualche esempio dei loro disegni, posso fare un ordine urgente di incisioni simili. Forse riusciremo a comprarci un vantaggio.", "Sei tornat<o/a> con i totem?", "Non sono un centauro, ma questo sembra un fascio di totem più che sufficiente. Mettendomi nei loro zoccoli, sarei felicissimo di riceverlo in dono. Ne ho persino procurati alcuni in più mentre eri via.\n\nParla con me quando sei pront<o/a> a fare la consegna--mi fido che farai la scelta giusta riguardo al clan con cui ci schieriamo.", 0x9d52128a, 0xa608090a, 0x7f0dbe84, 0xdffc89ab, 0xed457215, "....." },
  [93225] = { "Totem intagliati dei centauri", "Ottieni $N1 Carved Centaur Totem uccidendo centauri di qualsiasi clan in tutta ⟦Desolace=Desolanda⟧, poi portali a ⟦Gurda Wildmane=Gurda Manto Selvaggio⟧ al ⟦Ghost Walker Post=Presidio delle Ombre⟧.", "Ho notato che i centauri di clan diversi a volte si riuniscono lontano dagli insediamenti e commerciano tra loro. L'ho osservato per molte notti e, a quanto pare, con ogni clan; soprattutto, ho visto la moneta che usano: totem intagliati.\n\nCredo che possiamo volgere le sorti a nostro favore con i Gelkis o con i Magram, se consegniamo loro direttamente un bel carico di totem. Ho già cominciato a intagliarne qualcuno, ma dubito che si lasceranno ingannare facilmente senza qualche totem autentico.", "Sei tornat<o/a> con i totem?", "Sono splendidi... avevo sottovalutato la creatività dei centauri. Non avrei mai immaginato che una razza così piena di brutalità e crudeltà sapesse apprezzare storie raccontate attraverso degli intagli.\n\nImmagino che apprezzarli richieda molto meno fatica che realizzarli. Mi correggo: non avrei mai immaginato che i centauri avessero la pazienza di intagliare così tante storie nel legno. E dove lo trovano, il legno?\n\nIn ogni caso, parlami quando sei pront<o/a> a fare la consegna.", 0x9d52128a, 0x19fc2936, 0xb3fe9d43, 0xdffc89ab, 0xf0bec51b, "....." },
  [93226] = { "Comprare l'amicizia: Magram", "Porta la ⟦Totem Tote=Sporta per Totem⟧ al quartiermastro dei Magram al Magram Village, a ⟦Desolace=Desolanda⟧, per accrescere notevolmente la tua reputazione presso quel clan. Devi essere almeno Neutrale con i ⟦Magram Clan Centaur=Centauri del Clan Magram⟧.", "Io sceglierei di schierarmi con i Magram. Non c'è dubbio che oggi siano il clan dominante, nonostante le difficoltà del passato. Ho sentito rapporti secondo cui sono brutalmente ostili verso i Gelkis.\n\nProvo simpatia per entrambi i clan in guerra, e soprattutto per i Gelkis, ma questa è la loro guerra, non la nostra. Dovremmo schierarci con la parte che comporta meno rischi per la nostra causa. Credo che siano i Magram.\n\nPorta questo al loro quartiermastro al Magram Village, a sud-est.", "Che affari ha un forestiero con Gorhak?", "<Gli occhi di Gorhak si spalancano quando gli offri il fascio di totem intagliati, ma poi corruga la fronte mentre i suoi occhi tornano verso di te.>\n\nNon sono uno sciocco, forestiero. Questa donazione non è senza motivo. Vuoi qualcosa, da me o dal nostro clan. Non so cosa.\n\n<Con un solo gesto della mano, il quartiermastro si impossessa della borsa.>\n\nE oggi non mi importa quale possa essere il tuo secondo fine.\n\nBenvenuto al Magram Village, forestiero.", 0xf5fd14ba, 0x66df78e4, 0xe1f3c90b, 0xb619ffad, 0xcdce9709, "....." },
  [93227] = { "Comprare l'amicizia: Gelkis", "Porta la ⟦Totem Tote=Sporta per Totem⟧ al quartiermastro dei Gelkis al ⟦Gelkis Village=Villaggio dei Gelkis⟧, a ⟦Desolace=Desolanda⟧, per accrescere notevolmente la tua reputazione presso quel clan. Devi essere almeno Neutrale con i ⟦Gelkis Clan Centaur=Centauri del Clan Gelkis⟧.", "A prima vista, scommetterei che i Gelkis sono in difficoltà. Sono molto meno numerosi dei Magram, e i nostri esploratori di rado li sentono scorrazzare in giro.\n\nCiononostante, sono uno dei clan dominanti di ⟦Desolace=Desolanda⟧ e sopravvivono ancora oggi. Qualcosa di giusto devono pur farlo.\n\nSe vuoi fare pace con i Gelkis, porta con te questa sacca di totem al ⟦Gelkis Village=Villaggio dei Gelkis⟧, molto a sud-ovest. Per quanto primitivi, avranno probabilmente una specie di tesoriere.", nil, nil, 0x57c3db29, 0x68c32afb, 0xc65c6911, nil, nil, "...mm" },
  [93269] = { "Posta fino in vetta", "Porta la posta da ⟦Everlook=Lungavista⟧ fino alla locandiera Sebelia sulla vetta del ⟦Mount Hyjal=Monte Hyjal⟧.", "Ora che hai recuperato tutta la posta, puoi riportarla con te sul ⟦Mount Hyjal=Monte Hyjal⟧!\n\nNon dovrebbe essere un problema, vero?", nil, nil, 0x867c3a9d, 0xd94323a6, 0x3e2903a5, nil, nil, "...mm" },
  [93317] = { "La stagione dei granchi", "Raccogli 6 pezzi di ⟦Windsong Crawler Meat=Carne di Crostaceo di Soffiavento⟧.", "Conosci i Windsong Crawler? Vedi, questi granchi vivono solo nel ⟦Windsong Lake=Lago Cantovento⟧, qui su Zephras, e si possono pescare solo per poche settimane all'anno.\n\nCon tutta l'attività del culto di recente, non sono riuscito ad andare al lago a pescarli, e il tempo a disposizione sta finendo in fretta. Ti sarei grato se potessi andare a raccoglierne un po' per me. Di solito si trovano lungo le rive del lago e nei fiumi.\n\nMa sta' attent<o/a>, sono più cattivi di quanto sembrino!", "La carne di Windsong Crawler qui è abbastanza comune, ma sulle isole di Anvilas e Siroccas era una specie di prelibatezza. C'è stato un tempo, quando le correnti celesti erano aperte, in cui la gente del posto mi assaliva per averla quando facevo il viaggio fino a Shen'dramar o New Eldre'naar.\n\nNon riesco ad andare in quei posti da... be'... molto tempo.", "Che i venti mi benedicano, questa carne ha un aspetto fantastico!\n\nGrazie mille, {class}.", 0x6f40d8c7, 0x3826218b, 0xb3597e4b, 0x9e47a279, 0xca0b8646, "....." },
  [93318] = { "RICERCATA: Vulgara l'Insaziabile", "Uccidi Vulgara the Insatiable negli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧ e porta la sua testa a Danarii Bellowveil.", "Per ordine della conestabile Aonda dei Pacificatori, si pone una taglia sul flagello degli altipiani, Vulgara l'Insaziabile. Avvistato l'ultima volta sulla cima di un'altura appena a sud-ovest del ⟦Shen'dar Village=Villaggio di Shen'dar⟧, il terrore alato dei vuldren è estremamente pericoloso e va avvicinato con cautela.\n\nConsegna la testa della bestia a Danarii Bellowveil per ricevere la ricompensa.", "Mi serve la testa della creatura come prova dell'impresa.", "Come se non avessimo già abbastanza grattacapi tra il culto e i banditi degli altipiani, ci mancava solo un vuldren gigante a terrorizzare i nostri cittadini. Oggi hai fatto una gran cosa. Come promesso, ecco la tua ricompensa.", 0x26deadde, 0x95335eb7, 0x44a54b33, 0x7e44c040, 0xedf3a0ac, "....." },
  [93319] = { "Pietre del vento rubate", "Raccogli 10 Pilfered Windstone dagli Highlands Bandit negli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧.", "Qui su Zephras ci affidiamo sempre di più alle pietre del vento per la vita di tutti i giorni, quindi cerchiamo di tenerne una scorta di riserva per le emergenze. Ultimamente ho notato che alcune spariscono dai nostri magazzini.\n\nAbbiamo trovato pietre del vento addosso ai banditi che abbiamo catturato di recente, e sospetto che dietro le nostre carenze ci siano loro.\n\nSe ti trovi vicino alla grotta dei banditi a nord, ti dispiacerebbe dare qualche bella lezione e recuperare un po' delle nostre pietre del vento rubate?", "Probabilmente questi ladruncoli saccheggiano le nostre scorte da mesi. Ho cercato di convincere Aonda a organizzare un'incursione per ripulire una volta per tutte quella grotta dei banditi, ma lei non voleva allontanare dal villaggio i pochi Pacificatori che abbiamo.\n\nCon i cultisti che crescono di numero al ⟦Falaath Village=Villaggio di Falaath⟧, a sud, non posso darle torto.", "Grazie, {class}. Questo dovrebbe bastarci per ora. Ma se non riusciamo a sistemare presto le vie di rifornimento, qualche pietra del vento rubata sarà l'ultimo dei nostri problemi.", 0x41d7b2ca, 0x098aea7b, 0x414845c0, 0x9132cdaf, 0x4e8fd502, "....." },
  [93320] = { "Difendere la torre", "Fai rapporto a Yorana Windyreed alla torre di guardia orientale nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧.", "Mi è appena giunta notizia che il culto sta attaccando la torre di guardia del pilone, appena fuori dal paese! Ho mandato i pochi Pacificatori in più che abbiamo qui a cercare di sfondare le retrovie nemiche per dare sollievo ai difensori, ma ogni aiuto in più potrebbe fare la differenza tra la vita e la morte della nostra gente laggiù.\n\nTi prego, parti subito per la torre di guardia orientale e fornisci tutto l'aiuto che puoi.\n\nLa mia tenente, Yorana Windyreed, ha guidato i rinforzi. Se è ancora viva, potrà dirti come aiutare al meglio.", nil, "Per ora li stiamo tenendo a bada, ma sono più numerosi e i nostri combattenti cominciano a essere stanchi. Dobbiamo fare qualcosa per rompere lo stallo, e in fretta.", 0x0a49deab, 0x7f44b2b4, 0x98ee9961, nil, 0xbdc9cc11, "...m." },
  [93341] = { "Giardini Desolati", "Indaga sui Giardini Desolati vicino a Shen'dralas, poi torna da Mithera al tempio lì vicino.", "Come custode del giardino, era mia responsabilità assicurarmi che prosperasse.\n\nSapevo che sarebbe arrivato il giorno in cui non avrei più potuto occuparmene, così ho incantato una collana regalatami da mia figlia per trasformare una nuova generazione di germogli in treant, così che potessero vegliare sul giardino al posto mio. L'ho posta su un piedistallo incantato, al riparo in un piccolo santuario.\n\nIl giardino era in ottime mani. Devo sapere cosa è successo.", nil, "<Mithera ascolta in silenzio la tua spiegazione della situazione.>\n\nIl piedistallo è vuoto? La mia collana è... scomparsa?\n\n<Una profonda tristezza le attraversa il volto.>\n\nAvrei dovuto aspettarmelo. I verrospini e i centauri devastano queste terre da così poco tempo, eppure il danno che hanno già fatto è incalcolabile.\n\n{name}, anche se la magia ha abbandonato la collana, mi aggrappo alla speranza di riaverla. Saresti dispost<o/a> ad aiutarmi?", 0xd0ba0cf6, 0x0192d9da, 0x65717ea1, nil, 0x39cfc0c0, "...m." },
  [93362] = { "Cosa hanno fatto alle mie peonie", "Sfoltisci le piante nei Giardini Desolati, poi torna da Mithera a Shen'dralas.", "Ti prego, risparmiami i dettagli su come la vita possa essere stata distorta là. Il mio cuore è già abbastanza spezzato per la perdita della collana.\n\nMa mentre io piango, le piante soffrono.\n\n{name}, vorrei che tornassi al giardino e sfoltissi un po' di flora inferocita. Ti prego, sii rapid<o/a> e misericordios<o/a>: sentono dolore e sono già state ferite abbastanza. Se hai intenzione di cercare anche la mia collana, ti chiedo di dare priorità a quella prima di tornare nei giardini... nell'improbabile caso in cui tu la trovi.", nil, nil, 0x02a410c1, 0x39f93120, 0x9c26e5ed, nil, nil, "...mm" },
  [93383] = { "Contenuto sotto pressione", "Aspetta di poter aprire in sicurezza il Kit di Sopravvivenza Personale.", "Uno zaino robusto pieno di attrezzatura di sopravvivenza e ricevitori radio giace tra cespugli spinosi. Su una delle radio lampeggia una spia luminosa.\n\nTi allunghi verso lo zaino e la radio legata ad esso si accende con un ronzio.\n\n\"Pilota presente! Il Sistema di Posizionamento Gnomico sta stabilendo il collegamento!\n\nConferma dei contenuti da erogare: Kit di Sopravvivenza dell'Aviatore, Tre Giorni, Taglia Unica, Quantità Uno\n\nAttendere mentre il meccanismo di sicurezza si scarica in sicurezza prima dell'apertura.\"", nil, nil, 0xd81988f0, 0x793da55f, 0xec9cb1ef, nil, nil, "...mm" },
  [93394] = { "Incontro con il magistro", "Trova il magistro Kirandis nel tempio di Shen'dralas.", "Immagino che ora la tua curiosità ti attiri verso la grande struttura, vero? Bene!\n\nÈ improbabile che gli Shen'dralar ti accolgano a braccia aperte, ma finché ti muoverai con rispetto, non credo che incontrerai problemi.\n\nCon un po' di fortuna, il mio vecchio amico Kirandis potrebbe essere facile da trovare. Tra tutti, è il più propenso ad accogliere con cordialità la tua presenza.", nil, "È straordinario vedere che il potere dei piloni arde di nuovo con forza. Mi sorprende non averlo notato prima del tuo arrivo. Cominciavo a pensare che anche questo avrebbe presto subito la stessa sorte e che saremmo stati perduti nel tempo.\n\nGrazie per averci riancorati del tutto a Shen'dralas. Cerca di conoscere alcuni dei nostri abitanti. Potrebbero essere diffidenti con te, ma passerà.", 0x21131543, 0xbaafa318, 0x16504407, nil, 0x1aabfbb1, "...m." },
  [93404] = { "Marciume e rimpianto", "Avventurati a Maraudon, recupera una Fiala d'Acqua del Canto della Terra e riportala a Woodwyrd ai Giardini Desolati, a ⟦Desolace=Desolanda⟧.", "Io sono l'antico. Che si erge sopra di noi. Quello che ancora brucia nonostante tante piogge. Sento le sue fiamme nella morte. Per sempre gravato dal mio ultimo errore.\n\nNon so perché io sia maledetto a infestare questo luogo. Non capisco perché la morte non sia stata la fine.\n\nTi prego, spegni la fiamma. Cerca acqua pura da un burrone sacro. Un luogo simile esiste al di là di Mashan'she. Ho udito mormorii di quel luogo nel vento.\n\nMaraudon.", "<Woodwyrd resta in piedi, quasi immobile. Ti guarda attraverso, proprio come un tempo avresti potuto guardare attraverso i fantasmi di Shen'dralas.>", "<Le fiamme che prima consumavano la forma spettrale del treant si sono spente. Eppure il suo sguardo è vuoto. Passano diversi istanti di immobilità prima che si accorga della tua presenza.>\n\nIl mio tormento è finito. La pace si avvicina.\n\nNon c'è tempo per gli addii. Non c'è tempo di aspettare chi mi ha dimenticato.\n\nViaggiatore, ho un'ultima cosa da dirti. Un'ultima speranza per la tua missione.", 0x31232d72, 0x624e3edb, 0x6f389220, 0x280586b4, 0xecbdb345, "....." },
  [93406] = { "Consegne scongelate", "Trova $N1 Posta Smarrita sulle colline a nord di ⟦Everlook=Lungavista⟧ e riportala alla locandiera Vizzie.", "Quindi devi riportare la posta di ritorno sul ⟦Mount Hyjal=Monte Hyjal⟧, eh? C'è un piccolo problema...\n\nVedi, qualcuno è passato di qui e ha messo a soqquadro la posta in uscita appena qualche giorno fa! Probabilmente cercava soldi nella posta. È scappato sulle colline a nord di qui e non è più tornato. Probabilmente è stato fatto a pezzi da uno yeti o qualcosa del genere!\n\nComunque, se vuoi riportare la posta, dovrai prima andare a recuperarla!", nil, nil, 0x1b967bbd, 0x31a7b80c, 0xa6dd883b, nil, nil, "...mm" },
  [93407] = { "Una spina nella zampa", "Trova semi di spina nelle foreste in cima al ⟦Mount Hyjal=Monte Hyjal⟧ e riportali a Tiala Biancachioma.", "Dobbiamo migliorare le nostre difese qui e ci mancano le risorse per costruire fortificazioni. Abbiamo però tutta l'abbondanza della natura.\n\nCerca nella foresta dei cespugli di rovi e portami i loro semi. Con il potere della natura, faremo crescere le nostre difese.", nil, nil, 0x0cdff482, 0x2a63ab68, 0xd1bb5e93, nil, nil, "...mm" },
  [93422] = { "Blackout di Spinanera", "Uccidi il Corriere di Spinanera e confisca il suo messaggio.", "Il Re Selvatico ascolta attraverso ombre più antiche di Hyjal stessa. I suoi esploratori si muovono ora con uno scopo, spronati dalle rinnovate avanzate sia dell'⟦Horde=Orda⟧ sia dell'⟦Alliance=Alleanza⟧ in queste terre sacre. Il Patto di Spinanera sente la pressione della nostra resistenza e diventa ogni giorno più folle.\n\nDai la caccia al Corriere di Spinanera e interrompi la sua pista prima che riporti al suo padrone le loro importanti informazioni.\n\nSi sposta tra gli accampamenti. Osserva il suo percorso e abbattila. Portaci ciò che ha con sé.", nil, nil, 0x214855c4, 0x2ac6a8b8, 0x619edddf, nil, nil, "...mm" },
  [93429] = { "Sangue del mio sangue", "Uccidi 10 ⟦Lost Ones=Perduti⟧ nel ⟦Fallow Sanctuary=Santuario dei Perduti⟧.", "Anche se sono nostri consanguinei, i ⟦Lost Ones=Perduti⟧ del ⟦Fallow Sanctuary=Santuario dei Perduti⟧ sono diventati creature di pura violenza e odio.\n\nPer loro non può esserci redenzione né salvezza. Sono condannati a vagare per questa palude come creature senza mente e piene d'odio per tutta la vita.\n\nLe loro sofferenze devono finire. Qualcuno deve porre fine alla loro miseria. Un compito macabro, lo so, ma lo faresti per proteggere quelli di noi che restano?", nil, nil, 0x18916a9d, 0x3b5f5f4a, 0xdbc3d8f8, nil, nil, "...mm" },
  [93430] = { "Riprendersi l'esca", "Trova il ⟦Lost One Fisherman=Perduto Pescatore⟧ che ha rubato l'esca di Pelluk e riprendila.", "Stavolta l'hanno fatta grossa! Come se quei disgraziati non fossero già abbastanza un problema, uno di loro mi ha rubato l'esca portafortuna!\n\nStamattina ero fuori a pescare, quando uno è sbucato dal fango, mi ha tagliato la lenza ed è scappato con l'esca. Il ladro è quasi di certo uno dei pescatori dei ⟦Lost Ones=Perduti⟧, che spera di usare l'esca per sé.\n\nBe', le nostre scorte di pesce dipendono da quell'esca, quindi la rivoglio. I ⟦Lost Ones=Perduti⟧ pescano lungo le rive a est di qui. Trova quel ladro, {race}!", nil, nil, 0x42cf1db9, 0xb7ae8a79, 0x115f80e5, nil, nil, "...mm" },
  [93443] = { "Cassa di Spedizione Smarrita", "Consegna la Cassa di Spedizione Smarrita a ⟦Friz Frazzlespark=Friz Sfrigolascintilla⟧ al Porto Polveraccesa, nelle Radure del Fiume.", "<Sul fianco della cassa compare un'etichetta scritta a mano. Sulla destra c'è una mappa con un grande cerchio rosso lungo una costa sudorientale a nord di un tempio disegnato male, circondato dall'acqua e da qualche tipo di creature alate. Sulla sinistra c'è una nota in caratteri enormi.>\n\nPROPRIETÀ DI FRIZ SFRIGOLASCINTILLA\n\nPORTO POLVERACCESA\n\nATTENZIONE: NON manomettere. NON aprire senza supervisione.\n\n<In fondo all'etichetta compare un'ulteriore nota.>\n\nSe smarrita, restituire a ⟦Friz Frazzlespark=Friz Sfrigolascintilla⟧. Porto Polveraccesa. Radure del Fiume.", nil, "Dove hai detto di averlo trovato? Mi stupisce che tu sia ancora <intero/intera>. Grazie, <ragazzo/ragazza>.\n\nSai una cosa? Se hai l'abitudine di fare favori, scommetto che da queste parti più di uno avrà bisogno di te. Perché non ti fermi un po'?", 0xc2fa676d, 0x4f011a57, 0x87144b02, nil, 0xe68246cc, "...m." },
  [93444] = { "Esca per la bestia", "Uccidi un Guardiano Fiera della Notte, poi attira allo scoperto e uccidi Ghansurok usando la coscia di Guardiano Fiera della Notte sul crinale settentrionale della vetta.\n\nTorna con il cuore della chimera.", "La più feroce chimera vile di Hyjal è nota come Ghansurok. Le piace piombare sugli animali selvatici sorpresi fuori dalle loro tane. Non solo, rende anche i viaggi degli ippogrifi da e per Hyjal più stressanti del solito!\n\nPer prima cosa, dai la caccia a una delle Fiere della Notte nascoste nelle ombre della Vetta. Poi, metti la carne del felino abbattuto in un punto della cresta settentrionale dove si nutrono le chimere.\n\nAttira Ghansurok verso di essa. Uccidi la bestia e torna con il suo cuore. Marn lo studierà per aiutare a guarire Hyjal.", nil, nil, 0x3ef62b1d, 0x058f9d3e, 0x3a9a99d1, nil, nil, "...mm" },
  [93450] = { "Problemi fantasmali", "Prendi la spada incompiuta di Vindael e trova un modo per portarla nel regno degli spiriti, poi restituiscigli la Lama Fantasmale a Shen'dralas.", "Essere corporei ha le sue difficoltà, come sai, ma essere INcorporei è tutt'altra situazione. Cadrò attraverso QUESTA sedia? Inciamperò in QUEL gatto? Ma, peggio di tutto, rende impossibile il lavoro di ogni giorno!\n\nVedi questa spada sulla mia incudine? Ho cominciato a lavorarci migliaia di anni fa, ma sono morto prima di finirla. Ora mi sbeffeggia, E occupa prezioso spazio! Non posso lavorarci! Non posso SPOSTARLA!\n\nMi serve il tuo aiuto per, ehm, 'traghettarla' nel regno degli spiriti. Che ne dici?", nil, nil, 0xd72e86cf, 0xcbd84beb, 0x9039f695, nil, nil, "...mm" },
  [93451] = { "Problemi fantasmali", "Trova la spada incompiuta di Vindael e restituiscigliela a Shen'dralas.", "Ah, sembri una persona sensata. Probabilmente più sensata dell'ultimo zoticone che è passato di qui. Ho bisogno di un piccolo favore da te.\n\nVedi, avevo un problema. Il mio più grande capolavoro di forgiatura di spade è rimasto incompiuto prima della mia scomparsa, e avevo bisogno di qualcuno che mi aiutasse a portarlo nel mondo degli spiriti per poterlo finire. L'ultima persona è stata tanto gentile da aiutarmi, e ci è riuscita!\n\nOra ho un nuovo problema. Per colpa esclusivamente sua, l'avventuriero precedente non può più riportarmela.", nil, nil, 0xd72e86cf, 0x0c403f25, 0x9e806a58, nil, nil, "...mm" },
  [93459] = { "Altre orecchie di Al'Aketh", "Raccogli 10 Al'Aketh Cultist's Ear dagli Al'Aketh nella ⟦Shadowgale Forest=Foresta di Ventombra⟧, al ⟦Shrine of Akir=Sacrario di Akir⟧ o nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧ e portale a Vayn Moonclaw nella ⟦Shadowgale Forest=Foresta di Ventombra⟧.", "Il culto degli Al'Aketh di solito si tiene alla larga da questa foresta, temendo le voci che sia infestata... voci che siamo ben felici di alimentare. I druidi del mio ordine desiderano solo vivere una vita quieta e pacifica qui a Shadowgale, e loro la minacciano.\n\nMolti di noi hanno paura.\n\nVengo con un'offerta. Combatti i cultisti per noi e portaci le orecchie di quelli che uccidi. Ti ricompenseremo per ognuna che ci porterai, con denaro e, col tempo, con l'accesso ai nostri segreti, se dimostrerai di essere un vero amico.", "<Vayn ti fa un cenno con il capo.>", "Come promesso, ecco la tua ricompensa.", 0x91339b63, 0x4cc2e33c, 0x184326a2, 0xe91596f9, 0x53f5cf99, "....." },
  [93461] = { "Benvenuti al ⟦Shen'dar Village=Villaggio di Shen'dar⟧", "Parla con Rathiril Sunlance e Coriella Calmbreeze al ⟦Shen'dar Village=Villaggio di Shen'dar⟧.", "Hai proprio l'aria da \"Alto Ordine\". Chi ha antenati ⟦Highborne=Alti Nobili⟧ sembra sempre avere un lieve scintillio negli occhi che lo tradisce. Prima che ti metta al lavoro come si deve, dovresti presentarti al nostro anziano dell'Alto Ordine, Rathiril Sunlance. Lo trovi qui nella loggia principale, appena dietro l'angolo.\n\nAh, e passa anche da Coriella Calmbreeze: gestisce la locanda del posto e può darti alloggio e provviste, se ti servono.", "Questo posto non è granché, ma è casa.", "Allora ti sei presentat<o/a> a Rathiril? Ottimo. C'è parecchia tensione tra l'Alto Ordine e i Plasmatori di Venti di questi tempi, ma qui a Shen'dar mantengono i rapporti civili. Be', almeno nel villaggio. Quello che succede nelle terre selvagge resta nelle terre selvagge.\n\nOra che è fatta, hai l'aria di chi cerca qualcosa da fare con le proprie mani. Ho alcune cose da sbrigare, se te la senti di lavorare un po'.", 0x4c9d3c02, 0xe867665b, 0x8517821c, 0x777d1f13, 0xbc58bc08, "....." },
  [93464] = { "Il mago in visita", "Trova il mago di ⟦Desolace=Desolanda⟧ che conosce il potere del draenetista.", "Lascia che ti confessi una cosa, {name}. Anche se il draenetista è sacro per noi e ci mantiene sani di mente, nessuno qui lo comprende davvero.\n\nRicordo un mago che una volta venne al Rifugio dei Corrotti da ⟦Desolace=Desolanda⟧. Un umano di nome Azore. Temeva il potere del draenetista; diceva che non doveva finire nelle mani sbagliate.\n\nAll'epoca lo cacciammo per proteggere ciò che era nostro. Ultimamente, però, mi ritrovo a chiedermi cosa sapesse esattamente.\n\nTi chiedo di trovare questo mago, {race}. Le sue conoscenze potrebbero esserci di immenso valore.", nil, nil, 0x8dd4d8e6, 0x5dd0e284, 0x339bbfeb, nil, nil, "...mm" },
  [93465] = { "Appunti sul draenetista", "Prendi gli appunti di Gimashi sul draenetista e portali ad Azore Aldamort.", "Forse sarebbe più esatto dire che conosco qualcuno che ne sa qualcosa sul draenetista.\n\nVedi, gli stregoni delle ⟦Burning Blade=Lame Ardenti⟧ lo stanno studiando. È una sostanza che viene da oltre il Portale Oscuro, quindi è logico che chi pratica le arti più oscure voglia piegarla ai propri scopi. Non possiamo permetterlo, ovviamente.\n\nLa stregona che cerchi si chiama Gimashi. La trovi in cima alla sua torre, in un burrone a sud-est. I suoi appunti avranno le risposte che cerchi.", nil, nil, 0x187f109c, 0xbf8231d0, 0x92cd47bd, nil, nil, "...mm" },
  [93510] = { "Risvegliare i ricordi", "Trova l'ancora sul ⟦Lake Everstill=Lago Placido⟧ che il veterano di guerra ricorda dall'infanzia.", "È pesante restare in piedi a Hyjal, dove tanti compagni hanno incontrato una fine innaturale. La terra stessa risuona di dolore. Crateri pieni di cenere, ricordi troppo amari per essere dimenticati.\n\nEppure tu porti con te una scintilla dei Regni Orientali, un calore che sfida questa tristezza! Il mio amico d'infanzia Tobin si è arruolato insieme a me e, anche se ho speranza, temo per ciò che resta della sua anima.\n\nDa bambini passavamo i pomeriggi a far rimbalzare sassi sul ⟦Lake Everstill=Lago Placido⟧ a ⟦Redridge=Crestarossa⟧. Cerca un'ancora sulla riva e onora il nostro passatempo?", nil, nil, 0xb7e57583, 0x8561a9dd, 0x71592518, nil, nil, "...mm" },
  [93521] = { "Sfidante degli dei", "Porta gli Appunti di Ricerca di Ve'han a Tiala Biancachioma.", "Gli appunti di ricerca di Ve'han descrivono i suoi tentativi di rubare il potere degli Dei Selvatici, seguendo le ambizioni del suo capo, il Re Selvatico. I suoi successi furono pochi e sfortunati. Se fosse stato un druido più potente, probabilmente avrebbe divorato in fretta l'essenza di Jereman e ottenuto ancora più potere.\n\nI Guardiani di Hyjal al campo della vetta vorranno di certo essere informati.", nil, nil, 0x951c7368, 0xb149e0e3, 0xb771bdfa, nil, nil, "...mm" },
  [93546] = { "⟦Iron Ore=Minerale di Ferro⟧ Spettrale", "Cerca giacimenti di ferro spettrale intorno a Shen'dralas e raccogli $N1 ⟦Iron Ore=Minerale di Ferro⟧ Spettrale. Torna da Vindael a Shen'dralas quando ne avrai trovato abbastanza.", "Finalmente, FINALMENTE posso usare questa incudine per qualcosa di diverso da un tavolo monumentalmente pesante. Sono felicissimo di poter finalmente affinare la mia arte dopo secoli di pratica mancata.\n\nOra, probabilmente stai pensando: 'Vindael, sembra che tu stia preparando il terreno per un'altra richiesta.' E avresti ragione!\n\nMi serve rifornire la mia scorta di ferro, ma il tuo ferro ha un problema simile alla mia lama. Per fortuna, la soluzione è MOLTO più semplice.\n\n<Ti porge un piccone spettrale, senza darti la possibilità di rifiutare.>", nil, nil, 0x37890077, 0x8f2f06e2, 0xf348b687, nil, nil, "...mm" },
  [93547] = { "Una soluzione spinosa", "Pianta semi di spina vicino alla locanda, alla torre di deposito e al gruppo di alberi nell'accampamento dei druidi lealisti.", "Siamo costantemente sotto minaccia qui, sia dal Patto di Spinanera sia dalle creature ostili di Hyjal. Ma possiamo usare le spine a nostro vantaggio! Con un piccolo aiuto dal potere della natura, possiamo far crescere nuovi cespugli di rovi per proteggere il nostro recinto.\n\nPianta semi di rovo vicino alla strada per creare barricate accanto alla locanda, alla torre di stoccaggio e al gruppo di alberi vicino alla strada.", nil, nil, 0xfc8425cb, 0xce47b782, 0xacd69a25, nil, nil, "...mm" },
  [93551] = { "Lode", "Usa il Fodero Ricamato per incontrare il Veterano della Terza Guerra sul ⟦Mount Hyjal=Monte Hyjal⟧, vicino al cannone rotto al Riposo del Lutto.", "Hai fatto una deviazione per i desideri sbiaditi di un'anima perduta... grazie, {name}. La vista di un altro spirito al lago, che pensa a due amici in gara per vedere chi lancia più lontano... basta a portarmi a questo momento. La presenza si aggrappa al legame più forte con i vivi.\n\nNon abbiamo mai fatto rimbalzare un sasso da una parte all'altra...\n\n<Il fantasma contempla il lago.>\n\nRicordo. Incontrami al Riposo del Lutto, il luogo della nostra ultima battaglia, accanto al cannone spezzato vicino alla torre distrutta sulla scogliera.", nil, nil, 0x778df3da, 0x935c01b0, 0xb8fb452d, nil, nil, "...mm" },
  [93552] = { "Raccolta di pietre del vento", "Raccogli 15 Windstone Cluster dalle Raw Windstone al ⟦Thendal Grove=Boschetto di Thendal⟧.", "Le pietre del vento sono una risorsa vitale sull'isola di Zephras, perché racchiudono l'energia pura e concentrata dei venti stessi. Gli elementali del vento che un tempo vivevano qui a Zephras insieme a noi sono scomparsi parecchi anni fa e, da allora, la magia che sostiene quest'isola si sta lentamente affievolendo. Pur con i loro limiti, le pietre del vento restano una fonte di energia affidabile e per noi hanno un valore immenso.\n\nTroverai pietre del vento grezze sparse per il boschetto. Pensi di potermi aiutare a raccoglierle?", "Salve, {class}.", "Grazie mille per queste. Come elfi, abbiamo tutti un legame profondo con la magia, e queste pietre del vento diventano sempre più preziose mano a mano che la magia infusa in quest'isola dai grandi piloni d'ancoraggio continua ad affievolirsi.\n\nLe pietre del vento non sono l'unica cosa utile che puoi raccogliere da questa terra. Ti prego, prendi uno di questi manuali.", 0x2bcfca6e, 0xe8cd67c8, 0x3a9bfe02, 0x1c31b804, 0x7fc437ff, "....." },
  [93567] = { "Sbarcare il lunario", "Lascia che il Veterano della Terza Guerra racconti la sua storia vicino al cannone rotto al Riposo del Lutto.", "Questa scogliera di montagna a sudest... i resti della torre. Impressi nella mia mente, i loro strazianti urli echeggiano per sempre nei ricordi.\n\nPermettimi di liberarmi del peso e di raccontarti della mia sconfitta.", nil, nil, 0x820c93b5, 0xabb89cb9, 0x5423ebd7, nil, nil, "...mm" },
  [93568] = { "Collare Parzialmente Digerito", "Restituisci il Collare Parzialmente Digerito a qualcuno che ne sappia qualcosa. Presumibilmente si trova dentro o vicino a Shen'dralas, a ⟦Desolace=Desolanda⟧.", "<Tieni in mano un collare sudicio recuperato dal ventre di una creatura uccisa. Il materiale è cuoio di alta qualità, chiaramente cucito con cura.\n\nDa una fibbia corrosa pende un cartellino. Togli lo sporco con un gesto e vedi del testo thalassiano, anche se le lettere sono così stilizzate da risultare illeggibili, forse persino per chi conosce la lingua.\n\nOra ti trovi di fronte a una scelta. Ignorerai questo e andrai avanti con la tua vita, o tenterai l'impossibile e cercherai di dare pace al suo proprietario?>", "<Liranne prende il collare e lo esamina. Culla con delicatezza la targhetta di metallo nell'altra mano e accenna un breve sorriso leggendola.>", "Questo apparteneva a Dahlia, la mia migliore amica e la mia felina preferita. Dahlia... non ho mai avuto fantasia con i nomi. Le stava bene, però: era un fiore vivace e sbocciante nella mia vita.\n\nLe origini non sono granché emozionanti. Passavo accanto ad alcune dalie nel giardino quando questa gattina mi è balzata addosso! Così giocosamente minacciosa. Mi ha seguito fino al tempio e... il resto è storia!\n\nNon c'è bisogno che resti qui mentre mi perdo nei ricordi. Ecco qualcosa per il disturbo, grazie per aver fatto riaffiorare vecchi ricordi.", 0xf3699d03, 0x442eb618, 0x9cdce901, 0xc0d4291a, 0x428595c2, "....." },
  [93572] = { "Al servizio dei Draenei", "Proteggi i profughi draenei mentre attraversano la breccia di Kum'isha verso le ⟦Outland=Terre Esterne⟧. Nessuno dei profughi deve morire.", "Magari hai portato a Kum'isha una sfera di Draenetista, ma questo mostra a Kum'isha solo che sei fortunat<o/a>, non abile. Se vuoi guadagnarti la tua ricompensa, aiuterai i fratelli di Kum'isha a tornare a casa.\n\nKum'isha userà questa sfera per aprire una faglia, mentre altri draenei la attraverseranno. Qualunque pericolo ne esca, tu combatterai. Se qualcuno dei fratelli e delle sorelle di Kum'isha verrà ferito, puoi scordarti quella ricompensa.\n\nSei pront<o/a>, {race}?", nil, nil, 0x10a57fba, 0x6c75ef2f, 0x15570c74, nil, nil, "...mm" },
  [93574] = { "Carapace del Mangiacarogne", "Trova qualcuno interessato al Carapace del Mangiacarogne.", "<Con un terribile scricchiolio, hai staccato un pezzo di carapace del verme alla sua morte.\n\nNonostante le dimensioni enormi e il peso notevole, è deludentemente ordinario. Questa creatura non sembra il risultato di un crudele esperimento né di un allevamento attento per creare una bestia che divora tutto.\n\nÈ semplicemente un guscio impressionante, probabilmente desiderato solo dai collezionisti. Forse potresti trovare un collezionista, anche se, a parte il centauro, chi altro potrebbe essere vivo da queste parti?>", "<Kog'thug ti punta una lama alla gola prima che tu riesca a dire una parola.>", "<Gli occhi del verrospino scattano verso il carapace che sporge dal tuo zaino. Sbuffa una volta. Due. Addirittura tre, prima di allontanare la lama.>\n\nGrande Verme morto?\n\nGrande Verme scava nella terra dei ⟦Bristleback=Mantotergo⟧. Mangia nostri morti. Divora nostri piccoli.\n\nGrande Verme morto. Grande {race} eroe dei ⟦Bristleback=Mantotergo⟧. Grande {race} può stare nella terra dei verrospini. Per ora.\n\nCosa vuole Grande {race}?", 0xb71e239b, 0xc953a6e7, 0x2be73f97, 0xf5814f13, 0xb3446b3a, "....." },
  [93584] = { "La chiusura del culto", "Uccidi $N1 Adepto di Spinanera e $N2 Cultista Marchiato dal Selvaggio.", "Le terre intorno al ⟦Well of Eternity=Pozzo dell'Eternità⟧ sono invase dai seguaci del Re Selvatico. Molti un tempo erano al nostro fianco, legati dagli stessi giuramenti, ma la loro devozione si è inacidita in zelo sconsiderato. Ostacolano attivamente i nostri sforzi di curare Nordrassil e proteggere il Pozzo.\n\nNon fingerò che sia facile, né che le mie mani resteranno pulite. Tuttavia, non possiamo permettere che danneggino la nostra terra o ci colpiscano al fianco quando inizierà l'incursione maggiore.\n\nDiradane in fretta le fila, e che Elune perdoni ciò che la necessità richiede.", nil, nil, 0x1e74d135, 0x5943acb3, 0x4f3f4838, nil, nil, "...mm" },
  [93585] = { "Questa mia luce", "Scorta padre Tuttle fino al ⟦The Harborage=Rifugio dei Corrotti⟧.", "Oh, grazie al cielo, qualcuno di civile!\n\nSono venuto qui per conto della Chiesa della ⟦Holy Light=Luce Sacra⟧, per stabilire un contatto con i draenei del Rifugio dei Corrotti. Vedi, l'⟦Alliance=Alleanza⟧ non ha alcun punto d'appoggio da queste parti, e un po' di diplomazia con la gente del posto potrebbe aiutarci in questo senso. Dopotutto, la Luce accoglie tutti nel suo abbraccio!\n\nPerò la strada oltre questo ponte brulica dei parenti più selvaggi dei draenei. Se devo arrivare sano e salvo al Rifugio dei Corrotti, mi serve una scorta. Mi aiuterai, {class}?", nil, nil, 0xc51f3c34, 0x6d345a6d, 0xd75f821d, nil, nil, "...mm" },
  [93594] = { "La voce dei boschi", "Trova Woodwyrd ai Giardini Desolati di Shen'dralas, a ⟦Desolace=Desolanda⟧.", "Tra i treant nati dalla collana, uno in particolare si è distinto sopra tutti gli altri nel ricevere il dono della vita e della coscienza. Sospetto che, se gli altri sono caduti, lui possa essere l'unico rimasto.\n\nPassava le giornate a prendersi cura di ogni fiore e di ogni gemma, e le sere radicato nel terreno per fare da nido alle creature più piccole.\n\nSe è vivo, e prego che sia vero, potrebbe sapere cosa è successo.\n\nColtivo la speranza per il mio buon amico, Woodwyrd.", nil, "È troppo tardi. Per questi giardini.\n\nSono l'ultimo della mia generazione di custodi. Senza il dono, nessun altro può prendere il mio posto.\n\nLe erbacce hanno invaso la terra. I fiori sono inquieti. Gli alberi appassiscono.\n\n<Woodwyrd si volta lentamente verso l'antico imponente che illumina il cielo con il suo fuoco senza fine.>", 0x179df125, 0xb62417d2, 0x0360f0cc, nil, 0x5a5da0b9, "...m." },
  [93601] = { "Scaricare la colpa", "Cerca un verrospino importante al Rifugio dei ⟦Bristleback=Mantotergo⟧.", "Se vuoi recuperare il dono della donna, marcia a nord nella ⟦Valley of Bones=Valle delle Ossa⟧.\n\nÈ stato rubato. La colpa è dei verrospini. L'ho visto. Con i miei stessi bulbi oculari.\n\nSono loro il motivo per cui questo giardino è condannato a morire.\n\nNon perdonarli.", nil, "Grande {race} vuole collana? Be', Grande {race} non può averla!\n\nMistiche delle spine hanno bisogno di collana. Terra è più morta che morta. Spine non spuntano senza collana! Centauri camminano dove spine non spuntano. Vedi problema, o Grande {race} non vede?\n\n<Kog'thug interrompe il suo arrogante sproloquio e sbuffa pensieroso.>\n\nKog'thug ha idea. Vuoi scambio?", 0x20728ba5, 0x618550b3, 0xf961c073, nil, 0xd148e045, "...m." },
  [93604] = { "Il sangue di Agamaggan", "Avventurati nei ⟦Razorfen Downs=Sotterranei di Lamaspina⟧ e ottieni il Sangue Virulento di Agamaggan, poi riportalo a Kog'thug il Valoroso al Rifugio dei ⟦Bristleback=Mantotergo⟧, a ⟦Desolace=Desolanda⟧. Kog'thug ha tenuto a ricordare che il ⟦Blood of Agamaggan=Sangue di Agamaggan⟧ all'interno delle ⟦Razorfen Kraul=Gallerie di Lamaspina⟧ non sarebbe bastato.", "Grande {race} sentito dei ⟦Razorfen Downs=Sotterranei di Lamaspina⟧? <Sbuffo.> Certo che no! Grande posto nelle ⟦Barrens=Savane⟧. Tanti rovi. Impossibile non vedere.\n\nAgamaggan morto lì. Posto importante per tutti i verrospini. Ora Mantotergo non ammessi. Appartiene a Lamaspina che grugniscono col moccio. Lamaspina non rispettano storia dei verrospini!\n\nSangue di Agamaggan nutre la valle. Fa crescere rovi. GRANDI. Più grandi di piccola collana da elfo!\n\nVa' ai Sotterranei. Prendi sangue di Kog'thug. Sangue vecchio del kraul non va bene. Serve BUON sangue!\n\nDai sangue, prendi collana, vinci.", nil, nil, 0x1163fcf2, 0x0cfaf819, 0xf9fc90a3, nil, nil, "...mm" },
  [93606] = { "Rapporti ai ferri corti", "Placa la lite dei verrospini portando a Quolga un Bouquet Benevolo e il Sangue Virulento di Agamaggan. I fiori per fare il bouquet si trovano nei Giardini Desolati, vicino a Shen'dralas, a ⟦Desolace=Desolanda⟧.", "Quolga la Saggia compagna di vita di Kog'thug. Quolga grande mistica delle spine, per questo a Kog'thug piace lei. Quolga ha anche collana che Grande {race} cerca.\n\nProblema? Noi non in buoni rapporti. Lei arrabbiata perché noi rubato collana in primo luogo. Allora perché usare? Questo Kog'thug vuole sapere!\n\nMA! Quolga ama fiori quanto rovi. Sai dove prendere fiori? Dove abbiamo preso collana!\n\nForse lei non arrabbiata con Kog'thug se Grande {race} porta fiori e questo sangue per lui? Forse scambia collana!\n\nDille che Kog'thug dispiaciuto.", nil, nil, 0x0ea5db95, 0x04b7b218, 0xf669cb01, nil, nil, "...mm" },
  [93609] = { "Collana Desolata", "Porta la Collana Desolata a Mithera al tempio di Shen'dralas, a ⟦Desolace=Desolanda⟧.", "<La collana che cercavi è finalmente in tuo possesso, ma purtroppo la magia che conteneva è stata completamente esaurita. Pur non essendo l'ideale per la tua situazione attuale, almeno ne ha reso piuttosto facile l'acquisizione dai verrospini.\n\nProbabilmente è meglio riportarla a Mithera.>", nil, nil, 0xa5264068, 0x94f74381, 0x1aa1f2f8, nil, nil, "...mm" },
  [93615] = { "Gattini e gatti", "Trova i gattini di Shalla'kal nelle terre selvagge del ⟦Mount Hyjal=Monte Hyjal⟧.", "Oh, un bocconcino prelibato...\n\nNon temere, scherzo. Anche se potrei spezzarti la schiena come un ramo secco. Sono un semidio della natura selvaggia, dopotutto.\n\nSe vuoi ottenere il mio favore ed evitare il mio appetito, forse potrei gravarti di un compito?\n\nLa mia nidiata di piccoli si è allontanata per divertirsi. Poco su questa montagna potrebbe minacciarli direttamente, ma ci sono cose oscure in atto vicino alla vetta, e non voglio lasciare nulla al caso.\n\nPotresti controllare come stanno? In cambio del fatto che non ti mangio, naturalmente.", nil, nil, 0x6bc4255b, 0x8a6d99b7, 0x1ca59bb3, nil, nil, "...mm" },
  [93617] = { "Preda e predatore", "Dissuadi i cervi dal comportarsi da predatori.", "La gerarchia degli Dei Selvatici è piegata. Ora tutto è in movimento e la natura del mondo è malleabile come l'argilla!\n\nI miei simili non subiranno più le zanne dei predatori, perché ora daremo la caccia a tutti coloro che ci hanno divorato!\n\nTrema, fragile creatura, perché non hai né la forza né la velocità per dissuaderci!", nil, nil, 0x81831bf9, 0x46431856, 0xc7a3e625, nil, nil, "...mm" },
  [93644] = { "Diario Lacero", "Il testo suggerisce che l'autore di questo diario potrebbe trovarsi da qualche parte a Shen'dralas.", "<Trovato vicino a Shen'dralas, questo vecchio tomo sporco non conserva più gran parte della sua conoscenza.\n\nNel testo che rimane, le singole lettere sono difficili da distinguere dalle parole. All'inizio potrebbe risultare difficile da leggere, ma una di esse sembra essere un cognome.\n\nForse il suo autore, 'Evenshade', può essere trovato nelle vicinanze.>", "Ti serve qualcosa?", "Il mio diario? Certamente no, è andato perso secoli fa.\n\n<Mordent si riprende il tomo sporco e ne esamina la copertina. Inarca le sopracciglia per la sorpresa, ma le abbassa dopo aver aperto il libro.>\n\nHai davvero trovato il mio diario, ma ahimè, tutto ciò che vi avevo scritto è svanito. Non ho dimenticato cosa conteneva, ma non desidero pronunciarne neppure una parola.\n\nSe anche le sue pagine fossero sopravvissute in qualche modo, hai il mio permesso di tentare di ripristinarlo.", 0x20929582, 0xcdf8420d, 0x2116d4ce, 0x05240edc, 0x48075c68, "....." },
  [93663] = { "Smarrito in viaggio", "Trova il corriere scomparso e assicurati che il carico di Dar venga consegnato al Rifugio dei Corrotti.", "I draenei del Rifugio dei Corrotti sono pescatori abili e disposti a gettare le reti in acque più pericolose di quanto farei io. Ogni tanto commerciamo: loro ci danno parte del loro pescato e io offro un po' delle nostre provviste in eccesso.\n\nAvevo mandato un corriere goblin a consegnare il mio ultimo carico, ma non è mai tornato. Probabilmente se l'è mangiato un crocolisco.\n\nMa c'è di peggio: è in gioco la mia reputazione negli affari. Quel carico va ritrovato e consegnato al Rifugio dei Corrotti. Ti prego, trovalo, se ci riesci. Cerca vicino all'acqua, lungo la strada.", nil, nil, 0x6d5f7446, 0x57be44a4, 0xbeef4b7a, nil, nil, "...mm" },
  [93678] = { "Appunti Ridotti sulla Draenetista", "Riporta gli appunti trascritti di Azore a Magtoor al Rifugio dei Corrotti, nella ⟦Swamp of Sorrows=Palude del Dolore⟧.", "Ho preparato una trascrizione degli appunti di Gimashi sulla Draenetista. Sembra che i frammenti possiedano un certo grado di energia, ma una sfera pura di questa sostanza è molto più potente. Pare sia ciò che cercavano le ⟦Burning Blade=Lame Ardenti⟧.\n\nMolti degli appunti di Gimashi alludono a portali e rituali di evocazione demoniaca. Portali verso dove, o per evocare quali demoni, non saprei dirlo con certezza.\n\nPur non essendo le mie risposte definitive, ti prego di portare questi appunti con te nella palude. Spero capirai se non vengo con te.", nil, nil, 0x0ea3f6c6, 0x72a9cecd, 0x9a334fa2, nil, nil, "...mm" },
  [93679] = { "Visioni di un altro", "Guarda la visione di Onku insieme a Magtoor.", "Mi fa piacere rivederti, {name}. Ho letto gli appunti che ci hai portato e ho parlato della questione con Onku, il nostro veggente più anziano.\n\nDi recente ha ricevuto una visione che potrebbe condurci alla sfera di Draenetista. Vorremmo condividere con te le rivelazioni di quella visione, se vuoi unirti a noi per un momento?", nil, nil, 0x1fe9b9d1, 0x36a61bce, 0x7c4cafbe, nil, nil, "...mm" },
  [93680] = { "La chiave della città", "Procurati la ⟦Dalaran Sewer Key=Chiave delle Fogne di Dalaran⟧ per il magus Wordeen Bagliovuoto al ⟦Tarren Mill=Mulino di Tarren⟧.", "L'⟦Alliance=Alleanza⟧ aveva un esercito di maghi chiamato Kirin Tor. Per quanto fossero potenti, la demoniaca Legione Infuocata si dimostrò ancora più forte. In un colpo solo l'arcidemone Archimonde rase al suolo la loro città come fosse il giocattolo di un bambino. I superstiti furono ridotti a semplici vagabondi senza dimora.\n\nAlmeno finché non ricostruirono Dalaran. E per giunta proprio alle porte della Dama Oscura!\n\nMentre sei nei loro accampamenti, cerca qualcosa che ci permetta di entrare in città senza essere notati. Devo saperne di più.", "Cos'hai trovato? Un antico tomo? Una reliquia segreta?", "Una chiave delle fogne? Be', per fortuna non sono io a doverla usare.\n\nMa c'è del lavoro da fare prima che sia sicuro usarla.", 0xc31a2dd3, 0xa0350c6f, 0xab6858c6, 0x71ff321a, 0xcc1b3fbb, "....." },
  [93684] = { "Il ritrovato", "Trova i Draenei che cercano la Draenetista nelle ⟦Blasted Lands=Terre Devastate⟧.", "Pur non conoscendo altri insediamenti come il nostro, ho visto dei perduti a sud di qui, nelle ⟦Blasted Lands=Terre Devastate⟧. Sono molto simili a quelli del ⟦Fallow Sanctuary=Santuario dei Perduti⟧: ostili e senza mente. Ho presunto che fosse questo il destino toccato a tutti i nostri simili laggiù.\n\nTuttavia, se la visione di Onku indica un draenei solitario che vaga per una landa desolata, forse mi sbagliavo.\n\nTi chiamo ancora una volta, {name}. Trova questo draenei e aiutalo come puoi.", nil, nil, 0xe7198613, 0x26b199a5, 0x03963cc4, nil, nil, "...mm" },
  [93685] = { "Al servizio di Kum'isha", "Trova una ⟦Flawless Draenethyst Sphere=Sfera di Draenetista Perfetta⟧ nelle ⟦Blasted Lands=Terre Devastate⟧ e portala a ⟦Kum'isha the Collector=Kum'isha il Collezionista⟧.\n\nAttenzione: questa gemma è uno dei cristalli più rari di tutta Azeroth. Qualsiasi creatura di queste terre potrebbe avere con sé una ⟦Flawless Draenethyst Sphere=Sfera di Draenetista Perfetta⟧.", "La tua minuscola mente può comprendere la rarità di una sfera di Draenetista perfetta, {race}? I draenei hanno passato vite intere alla ricerca di un solo cristallo di questo tipo, solo per incontrare destini orribili, con il loro scopo incompiuto.\n\nDunque ti presenti davanti a Kum'isha, sapendo ciò che Kum'isha ha chiesto, e vuoi comunque aiutare? Molto bene, {race}... In qualsiasi momento durante i tuoi viaggi per queste terre, se trovi una sfera di Draenetista perfetta, riportamela e ti ricompenserò con ricchezze oltre i tuoi sogni più sfrenati.", nil, nil, 0x81cce1f7, 0x6982530b, 0x09d08d4a, nil, nil, "...mm" },
  [93686] = { "Le imprese di Kum'isha", "Trova e riporta una ⟦Flawless Draenethyst Sphere=Sfera di Draenetista Perfetta⟧ a ⟦Kum'isha the Collector=Kum'isha il Collezionista⟧.", "Anche se la faglia è stata solo un successo parziale, Kum'isha deve continuare i suoi tentativi.\n\nLa speranza dei draenei è ardente quanto la tua avidità di ninnoli, {race}. Torna in queste terre maledette e recupera un'altra sfera di Draenetista perfetta.\n\nNaturalmente, la scelta di accettare questo compito è interamente tua *sogghigna*.", nil, nil, 0x25629eb7, 0x0760f0e7, 0x0d0d9783, nil, nil, "...mm" },
  [93689] = { "Amico del Kirin Tor", "Parla con l'arcimaga Celindra nella città di Dalaran.", "Questa è una notizia eccellente! Ora che a Dalaran è tornata la pace, non vedo perché il Kirin Tor non dovrebbe accoglierti a braccia aperte!\n\nTi prego, presentati al consiglio al più presto. Sono certo che non vedranno l'ora di conoscere <il/la> <salvatore/salvatrice> della città.", nil, nil, 0xa01b2371, 0x8dfa9ac1, 0x71e69736, nil, nil, "...mm" },
  [93733] = { "Saluti da un ingrassatore", "Presentati agli altri qui, così non si sorprenderanno di vedere uno sconosciuto aiutare con parte del lavoro. <PH>.", "Presentati agli altri qui, così non si sorprenderanno nel vedere un estraneo che dà una mano con parte del lavoro. <PH>", nil, nil, 0x030f285c, 0xb125a0b0, 0xf3ac41b2, nil, nil, "...mm" },
  [93735] = { "Il costrutto guasto", "Trova Riaani Nightwind sul lato occidentale di Valanaar.", "Da sempre i Plasmatori di Venti si occupano della cura degli strumenti e dei congegni magici che ci furono donati dagli spiriti del vento, tra cui la miriade di costrutti magici sparsi per l'isola. Da quando gli spiriti ci hanno lasciati, solo pochissimi di questi funzionano ancora.\n\nUno dei pochi costrutti ancora funzionanti di Valanaar si è danneggiato. Abbiamo mandato uno dei nostri artigiani a ripararlo, ma potrebbe aver bisogno di aiuto. Recati all'estremità occidentale della città e offrigli tutta l'assistenza che puoi.", nil, "<Riaani ha la faccia sepolta sotto le pesanti piastre corazzate del costrutto e cerca di lavorare ai meccanismi sottostanti. Non si accorge minimamente della tua presenza.>\n\nChe le tempeste lo maledicano, dov'è il nucleo?! A chi è venuto in mente di rimuovere anche il Gyrozephyr? È un miracolo che i venti di questo costrutto non si siano ancora dissolti del tutto!", 0x3b580ff6, 0xb230d6e2, 0x9c9b9f2d, nil, 0xd94b28e4, "...m." },
  [93736] = { "Spiriti indesiderati", "Raccogli 10 Wind Hollow Essence dai Wind Hollow nella ⟦Shadowgale Forest=Foresta di Ventombra⟧.", "La preoccupazione principale dei Plasmatori di Venti è capire meglio perché gli spiriti ci abbiano lasciati, e cosa potremmo fare per riportarli indietro. Una curiosa presenza nella ⟦Shadowgale Forest=Foresta di Ventombra⟧, a nord, è quella di una strana forma di spiritello del vento che alcuni chiamano «hollows». Sappiamo poco di loro e del perché si trovino lì, ma sappiamo che hanno cominciato a comparire dopo che gli spiriti del vento ci hanno lasciati.\n\nHo bisogno che tu vada laggiù a disperderli. Raccogli i loro resti e portali qui.", "La Foresta di Ventombra è un luogo pericoloso. Alcuni dicono perfino che sia infestata. Io non ci credo affatto, ma so bene che non è un posto per i deboli di cuore, né per chi è impreparato.", "Maneggiare queste essenze mi riempie di un senso di... profonda inquietudine. Riesco quasi a percepire un'aura maligna e piena di rimpianto che emana da esse. C'è da sentirsi mancare.\n\n<Endaria rabbrividisce leggermente.>\n\nNon ho alcuna voglia di studiarle ancora.", 0x4f4a02b2, 0x24071ed5, 0x120ac132, 0x5f247307, 0x64b49c6f, "....." },
  [93737] = { "Il costrutto guasto", "Parla con Riaani Nightwind e ascolta ciò che ha da dire.", "Oh, salve. Ti ha mandato Ayessa ad aiutarmi? E va bene.\n\nNon so cosa possa fare <un/una> principiante come te, ma se mi dai un momento per tirare fuori la testa dalle viscere di questo costrutto, forse mi verrà in mente qualcosa con cui puoi renderti utile.", "Non riesco proprio a immaginare perché qualcuno voglia rubare questi componenti a questo costrutto. A parte il gyrozephyr, non hanno quasi nessuna utilità pratica. E perfino il gyro sarebbe pressoché inutile fuori dallo scopo per cui è stato creato.", "Grazie per aver recuperato questi materiali. Immagino che procurarsene alcuni non sia stato per niente facile.\n\nCon questi pezzi posso rimettere in funzione il costrutto. Da lì in poi possiamo solo sperare che la sua memoria sia intatta e che possa dirci chi ha preso i suoi componenti.", 0x3b580ff6, 0x20bf5d1d, 0xc9fcddd9, 0x57705db0, 0xf88bb130, "....." },
  [93738] = { "Il costrutto guasto", "Torna a fare rapporto ad Ayessa Cantalba a Valanaar.", "Brightwish, eh? Quindi l'Alto Ordine voleva rimuovere questi componenti per qualche motivo. Ma perché?\n\nL'Alto Ordine è sempre stato invadente, sempre ansioso di sperimentare con la magia degli spiriti del vento. Sono fin troppo sfrontati, e abbiamo proibito loro severamente di immischiarsi nelle conoscenze di competenza dei Plasmatori di Venti, ma ultimamente stanno mettendo alla prova la nostra pazienza.\n\nPenso che dovresti riferire ciò che hai scoperto ad Ayessa Cantalba. Lei saprà dirti cosa fare.", nil, "Molto interessante. Quindi è stato l'Alto Ordine a far guastare il costrutto?\n\nConosco Belathaan. È il cugino di Valennia Stormfist, e sua madre era una Plasmatrice di Venti. È deludente che sia coinvolto in questa faccenda.\n\nHo bisogno di riflettere un momento.", 0x3b580ff6, 0x29d7b548, 0x98b46a4e, nil, 0xe4724d1e, "...m." },
  [93739] = { "Alla scoperta dell'⟦Horde=Orda⟧", "Parla con Nazgrel a Grommash Hold per ricevere altre istruzioni. Segui le istruzioni ricevute per trovare Vol'jin, ⟦Cairne Bloodhoof=Cairne Zoccolo Sanguinario⟧ e ⟦Lady Sylvanas Windrunner=Dama Sylvanas Ventolesto⟧ e parlare con loro.", "Azeroth è un mondo vasto, e il territorio dell'⟦Horde=Orda⟧ è immenso. ⟦Undercity=Sepulcra⟧, Orgrimmar e ⟦Thunder Bluff=Picco del Tuono⟧ hanno popoli e culture davvero unici.\n\nSe devi essere ospite dell'⟦Horde=Orda⟧ qui su Azeroth, ti farebbe bene visitare una dopo l'altra tutte le nostre capitali. Parla con il mio consigliere Nazgrel per avere indicazioni.", nil, "Dunque sei <tornato/tornata>. Spero che tu abbia imparato molto durante il viaggio.\n\nA quanto mi risulta, la tua gente si sta ancora stabilendo a Mulgore. Mentre li aspetti, ti consiglio di esplorare il territorio intorno a Orgrimmar. Le ⟦The Barrens=Savane⟧, in particolare, hanno sempre bisogno di avventurieri volenterosi come te.", 0x7968676a, 0x9721d08e, 0xc1326b85, nil, 0x9b3fc549, "...m." },
  [93740] = { "Sangue per sangue", "Raccogli 10 Al'Aketh Windstone Charm dai cadaveri dei cultisti Al'Aketh nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧.", "Stamattina alcuni dei nostri novizi dei Plasmatori di Venti sono stati trovati morti negli altopiani. Non possiamo esserne certi, ma con ogni probabilità i responsabili sono gli Al'Aketh. I Plasmatori di Venti ripagano sangue con sangue, ogni volta.\n\nDirigiti a nord e uccidi tutti gli Al'Aketh che incontri. Portami i loro amuleti di preghiera di pietra del vento come prova dell'opera compiuta. Noi non perdoniamo e non dimentichiamo.", "Gli Al'Aketh si abbandonano al loro fanatismo sanguinario da fin troppo tempo. Questo è solo l'inizio della resa dei conti che li attende.", "<Ayessa sembra scossa e assente mentre le consegni gli amuleti di pietra del vento.>\n\nNon badare a me, {name}. Oggi è stata solo... una giornata difficile. Grazie per ciò che hai fatto finora per i Plasmatori di Venti.", 0x8fdc4a0a, 0xc45880fd, 0xe1adb7e7, 0xe653122a, 0x7adc4448, "....." },
  [93746] = { "Una risposta ferma", "Affronta Belathaan Brightwish lungo la strada per il ⟦Shrine of Akir=Sacrario di Akir⟧.", "L'Alto Ordine è stato avvertito delle conseguenze dell'immischiarsi negli affari dei Plasmatori di Venti. Credo che dobbiamo dare l'esempio con Belathaan e rimandarlo all'Alto Ordine con qualche livido e un sano rispetto per i limiti che abbiamo fissato.\n\nBelathaan è stato visto lasciare la città, diretto a nord verso il ⟦Shrine of Akir=Sacrario di Akir⟧. Non so perché stesse andando laggiù, ma affrontarlo da solo sulla strada è la scelta più sicura. Trovalo e mettigli un po' di paura in corpo.", nil, "Aspetta... cosa?! Belathaan... è morto?\n\n<Ayessa ascolta il tuo racconto dell'accaduto.>\n\nL'Alto Ordine si incontrava con gli Al'Aketh per discutere di pace? Non c'è pace possibile con il culto, sono fanatici assassini. Cosa pensava Elaadrin, mandando Belathaan da solo a trattare con loro?\n\nNon pensarci più, {name}. Non è colpa tua. La colpa è dell'arroganza dell'Alto Ordine, ancora una volta. Ti sei solo <trovato/trovata> nel posto giusto al momento sbagliato.", 0x2e10a415, 0x87bb368c, 0x049e9393, nil, 0x348cc12c, "...m." },
  [93747] = { "Dalla violenza al verde", "Pianta i Semi Incantati vicino alla balista in rovina, alla catapulta in rovina e alla macchina volante in rovina.", "Le vecchie carcasse della guerra si stanno decomponendo e arrugginendo, ma possiamo accelerare il processo di recupero.\n\nPrendi questa borsa dei semi che hai raccolto prima. Ho dato loro un piccolo aiuto magico per accelerarne la crescita. Piantali vicino ai vecchi macchinari da guerra e lascia che crescano e li ricoprano. I ricordi della guerra svaniranno nel passato e la natura riprenderà il suo spazio.", nil, nil, 0xc53cebe8, 0x7e1203ac, 0xe11a4e9b, nil, nil, "...mm" },
  [93759] = { "L'abbondanza della natura", "Raccogli $N1 Taglio di Cervo di Hyjal da un Cervo di Hyjal incontaminato e $N2 Tubero Dardo Scarlatto per lo stufato dell'eremita.", "Hai fatto un buon lavoro e hai aiutato molto me e la montagna.\n\nSto giusto preparando uno stufato e lo condividerei volentieri se mi aiutassi a raccogliere alcuni degli ingredienti.\n\nPur non gradendo uccidere gli animali selvatici, il ciclo della vita richiede sostentamento. Un equilibrio di ingredienti ci servirebbe bene. Qualche Taglio di Cervo di Hyjal dai cervi di Hyjal si abbinerebbe bene alle radici amidacee delle piante di Tubero Dardo Scarlatto che crescono nei luoghi verdi qui vicino.", nil, nil, 0x5beaeffa, 0x1f0892b4, 0xf15ee8f2, nil, nil, "...mm" },
  [93773] = { "Il Patto", "Torna a riferire a Ketharas sul ⟦Mount Hyjal=Monte Hyjal⟧.", "Sembra che Ve'han sia riuscito a rubare almeno una parte del potere di un Dio Selvatico. Una cosa simile mi pare incredibile, eppure eccoci qui.\n\nE cos'è questo 'Patto' di cui parlava Ve'han? {name}, devi tornare da Ketharas. Digli ciò che hai appreso.\n\nMi dispiace dirlo, ma è probabilmente ben oltre le tue capacità abbattere un nemico come Ve'han. Solo il potere di... be', gli stessi Dei Selvatici potrebbe essere in grado di contrastare questa magia.", nil, nil, 0x119207ff, 0xed7ba21f, 0x00ac7e53, nil, nil, "...mm" },
  [93786] = { "Un Messaggio di Sangue", "Uccidi $N1 ⟦Meadowsbrook Farmhand=Bracciante di Rivoprato⟧, poi torna da Krom'rosh con la notizia del tuo successo.", "La tua lama ha sete di sangue umano, {name}?\n\nQualche anno fa, i disertori umani si sono presi una piccola fattoria a sud-ovest, oltre il fiume. Con una zona così ricca di legname e pietra, era solo questione di tempo prima che estendessero il loro dominio fino alla rocca sulla costa orientale chiamata Farholde.\n\nI nostri primi scontri si sarebbero conclusi a nostro favore, se fossimo stati in numero sufficiente. È ora di ricordare loro che ci siamo.\n\nSabota il loro lavoro nei campi. Niente prigionieri. Manda loro un messaggio chiaro.", nil, nil, 0x356cfc07, 0x5be31a62, 0x997a25a0, nil, nil, "...mm" },
  [93787] = { "Cibo a Portata di Mano", "Ruba $N1 ⟦Feed Satchel=Sacca di Mangime⟧ dalla fattoria dell'⟦Alliance=Alleanza⟧ a ⟦Meadowsbrook=Rivoprato⟧, poi torna da Krom'rosh.", "Gli umani di queste terre godono da tempo del calore, delle comodità e del sostentamento che esse offrono. È ora di cominciare a negare loro questi piaceri.\n\nCerca le provviste dei nostri nemici nella fattoria a sud-ovest. Prendi tutto ciò che trovi.\n\nNon darà la stessa soddisfazione di insanguinare una lama, ma rallentarli ci darà il tempo di preparare la prossima mossa.", nil, nil, 0x92341ffc, 0xa56852d0, 0x5a1cd66b, nil, nil, "...mm" },
  [93788] = { "Lame in prestito", "Recupera $N1 Ascia del Falegname dai boscaioli del Campo di Disboscamento di Turner per Kreza Spinascura a Rog'mar.", "Con la presenza umana a sud e il Crepuscolo a ovest, la battaglia per le risorse è diventata difficile. Ma perché raccogliere risorse tra i nostri nemici quando le loro lame bastano?\n\nSegui il fiume verso sud fino al mulino. Quando senti il fischiettare dei falegnami tra gli alberi, muoviti con cautela. Quando se ne presenta l'occasione, colpisci forte e in fretta.\n\nIo resterò qui a tenere la forgia ben calda. Gur'dok smonterà le lame mentre io forgio armi con i loro stessi materiali.", nil, nil, 0x4c24b02a, 0x30e0c2f0, 0x82fe6d0e, nil, nil, "...mm" },
  [93791] = { "Parlare con Belann", "Parla con Belann Windwood a Valanaar.", "{name}, è chiaro che la tua abilità con la magia sta crescendo, e credo sia giunto il momento che tu prenda parte a una delle tradizioni più antiche dell'Alto Ordine per i maghi giovani e promettenti. È ora che tu crei un tuo focus degli incantesimi.\n\nCerca Belann Windwood a Valanaar. Fabbrica bastoni e bacchette per l'Alto Ordine da più di un secolo, quindi sarai in buone mani.", nil, "Ah, tu devi essere {name}, giusto? È confortante vedere giovani maghi desiderosi di imparare le nostre usanze e la nostra storia. Vieni, ti spiegherò i prossimi passi per creare il tuo focus degli incantesimi.", 0x9eee1307, 0xdac9b99f, 0x9e12128a, nil, 0x293bd11b, "...m." },
  [93797] = { "Rami nel vento", "Porta un ⟦Wind-Infused Bough=Ramo Infuso di Vento⟧ a Belann Windwood a Valanaar.", "È una tradizione consolidata che i giovani maghi creino il proprio focus degli incantesimi quando hanno dimostrato un certo grado di abilità magica. Di solito si comincia raccogliendo un ramo caduto dai nostri alberi più antichi, perché conservano ancora tracce del vento elementale.\n\nI più adatti li ho trovati vicino al santuario del vento, appena a sud del ⟦Falaath Village=Villaggio di Falaath⟧. Va' e portami un grosso ramo: ti insegnerò le tradizioni mentre creiamo il tuo focus degli incantesimi.", "Ogni anno che passa, a Zephras nascono sempre meno persone dotate di talento per la magia.\n\nSono lieto di vedere giovani maghi come te prendere parte alle nostre tradizioni più antiche, per mantenere viva la nostra storia e la nostra cultura.", "Grazie, {name}. Sento davvero le energie elementali in questo ramo, in attesa di essere imbrigliate da chi ha il dono per farlo. Ne verrà fuori un eccellente focus degli incantesimi.\n\nQuesto ramo ti ha forse cantato? Capita spesso che sia il ramo a scegliere <il/la> {class}, e non il contrario.\n\n<Belann ridacchia mentre ti prende delicatamente il ramo.>", 0x53b7cabb, 0xbb3c4f26, 0x55b3e7d7, 0xf0384662, 0x12ab22f5, "....." },
  [93825] = { "Benedizioni legate alla corteccia", "Raccogli $N1 ciuffi di Muschio Velo di Luna e torna da Suma Chiomamuschio.", "Vuoi imparare da noi? Gli alberi di Hyjal parlano a noi. La loro corteccia custodisce vita, e su di essa cresce il muschio che chiamiamo Velo di Luna. È morbido, verde e forte dell'anima della montagna. Ci serve questo muschio per curare le nostre ferite e benedire le radici.\n\nVai, gentile. Cerca i vecchi alberi dove la nebbia si attacca e il sole si nasconde. Prendi muschio Velo di Luna dalla loro corteccia e riportalo a me. Con esso, rimargineremo ciò che ci fa male.", nil, nil, 0x5c92c768, 0x3a31960e, 0xc8dcf0cc, nil, nil, "...mm" },
  [93826] = { "Terrore per i Legnomorto", "Sconfiggi $N1 Totemico Legnomorto e $N2 Custode del Vil Legnomorto e torna dall'Anziano Parlapino.", "Le vecchie vie sono perdute per i Legnomorto. I loro artigli strappano il legno, i loro cuori bruciano di rabbia. Colpiscono noi, e la natura selvaggia trema.\n\nTu, amico dei mezzorsi, puoi aiutare. Va' alla loro tana. Mostra loro che la natura selvaggia non si piega all'avidità. Uccidi chi insozza le radici e torna quando le loro grida svaniranno dagli alberi. Metti fine ai loro sapienti, saggi ma tristi. Essi contorcono viti vili e sozze.\n\nFai questo e parleremo agli spiriti del tuo nome.", nil, nil, 0xb297c2ea, 0xd54d0578, 0x9bf77e21, nil, nil, "...mm" },
  [93827] = { "Protezioni spazzate dal vento", "Raccogli $N1 Amuleto d'Arpia Incantato e torna da Thobon Linfartiglio.", "I venti della montagna portano oscuri presagi. Le arpie nidificano in alto dove le nostre zampe non vanno. Le gemme che indossano hanno forte potere. Legate ai nostri amuleti, ci proteggono dalla maledizione e legano gli spiriti alle nostre difese.\n\nMa la salita è dura e le arpie colpiscono con artiglio e tempesta. Se sei forte come dicono, va' alle alte rupi dove urla il vento. Le terre delle arpie sono a Hyjal centrale, le vediamo volare sopra di noi, a nordest. Prendi gli amuleti alle streghe del cielo e portameli.", nil, nil, 0x0ac14840, 0x4d08bc3a, 0xa5321dcf, nil, nil, "...mm" },
  [93828] = { "Erbe della conca", "Raccogli $N1 Erbe Essiccate Appese nei dintorni della Tana dei Pelledura e riportale a Fennar Chiomamuschio.", "Il respiro della montagna è umido qui vicino alla sorgente, e le mie erbe non si seccano in quest'aria densa. Quando i nostri parenti tornano dalla natura selvaggia, appendono i loro zaini dove le radici permettono una buona aria, sparsi per la tana.\n\nVai ora. Trova i fasci di erbe secche appesi intorno alla nostra casa e portameli. Con essi tesserò fasce e protezioni per mantenere forti i nostri spiriti.", nil, nil, 0x77ca1fc6, 0x154b0313, 0x1c3f1aa6, nil, nil, "...mm" },
  [93830] = { "Acqua di Hyjal", "Riempi un otre fornito da Fennar Chiomamuschio nello stagno fuori dalla tana dei mezzorsi Legnomorto.", "I Legnomorto vivono presso uno stagno nato dal disgelo del Monte Hyjal. Quell'acqua è pura, forte del respiro della montagna. La usiamo per i nostri infusi e per salvare le radici dalla morte.\n\nQui le sorgenti scorrono lente. La nostra fonte va salvata e usata con cura. Ma il loro stagno scorre di vita, potrebbe riempire la nostra tana due volte. Portami un otre pieno di quell'acqua, amico. Gli spiriti benediranno i tuoi passi e la nostra tana berrà a fondo il dono della montagna.", nil, nil, 0x62b45624, 0x99749f05, 0xb35febbe, nil, nil, "...mm" },
  [93831] = { "Marmellata di Zampadolce", "Raccogli $N1 Bacche dell'Orso a Hyjal e torna da Osi Zampanebbia.", "Hai odore di venti di montagna, forte e libero! Ho un compito, se le tue zampe non sono occupate.\n\nAmiamo le bacche d'orso, sono tonde, rosse e dolci come miele dopo il gelo. Cercale all'ombra degli alberi. Troppe rocce affilate e ali furiose perché noi raggiungiamo il cespuglio più maturo.\n\nPortamene un mazzo e preparerò la Marmellata di Zampadolce! Il mio dolce migliore, e ne condividerò un assaggio.\n\nAffare fatto?", nil, nil, 0xd1ab83fa, 0x6260d4c2, 0x362cb3cc, nil, nil, "...mm" },
  [93832] = { "Frantumare i Vegliapietra", "Distruggi $N1 gargoyle Sentinella Eterna nella base distrutta dell'⟦Alliance=Alleanza⟧ nell'alta Hyjal e torna dall'Anziano Zampanebbia.", "Gli alti pendii custodiscono ali di pietra. Bestie di roccia. Mezze vive, mezze morte. Mani impure le scolpiscono. Non fidarti della loro posa immobile. Questi occhi aspettano un passo falso.\n\nI nostri piccoli non conoscono il rischio. Una zampa troppo vicina e la pietra si sveglia con artiglio e zanna.\n\nVai, frantuma queste forme maledette. Spezza le loro ali, schiaccia i loro frammenti e lascia che la montagna respiri libera.", nil, nil, 0x8a1f7728, 0xd4ca3a87, 0xe2c1ee12, nil, nil, "...mm" },
  [93833] = { "Saggezza malvagia", "Porta $N1 corpi di gufo all'Anziano Parlapino nella Tana dei Pelledura a Hyjal.", "I gufi di Hyjal sono più che piume e volo. I loro artigli, le loro piume, persino le ossa sussurrano della natura selvaggia. Usiamo questi doni per forgiare talismani, amuleti che legano gli spiriti e proteggono i nostri simili.\n\nMa i gufi non donano liberamente. Devi prendere ciò che la montagna offre. Uccidi $N1 gufi e portami le loro carcasse.\n\nSì, ti chiediamo di riportarci l'intero corpo, perché non sprechiamo nulla di ciò che ci danno creature così aggraziate.", nil, nil, 0xb4d1a9ff, 0x4a3e9b6b, 0xb03a5a16, nil, nil, "...mm" },
  [93834] = { "Scarabei della tana", "Raccogli $N1 Pezzi di ⟦Beetle=Scarabeo⟧ della Tana per Dala Faucegentile.", "Scarabei della tana! Sono una piaga... e ora scavano nella nostra tana più che nella loro. Li respingiamo e agitiamo clave quando li vediamo strisciare, ma sono veloci e nascondersi nel buio è il loro scudo.\n\nSe li vedi mentre sali nella nostra tana, schiacciali! Prenderemo i loro gusci frantumati e ne faremo un pasto, così non è tutto male.", nil, nil, 0xaed0eb27, 0x34fe3623, 0xdd4a4bfd, nil, nil, "...mm" },
  [93835] = { "Affrontare Lorthuna", "Prendi il portale verso le ⟦Rohashi Spires=Guglie Rohashi⟧, qui sopra, e unisciti a Elaadrin Evengale e Ayessa Cantalba nello scontro con la somma sacerdotessa Lorthuna.", "Lorthuna è fuggita sulle guglie qui sopra attraverso una specie di portale. Ayessa ed Elaadrin le sono andati dietro. È successo solo pochi istanti fa.\n\nTemo di aver preso un colpo di troppo: per me il viaggio finisce qui. Attraversa il portale, trova Elaadrin e aiutali a fermare Lorthuna.\n\nA meno che non arrivino presto i rinforzi che Elaadrin e Ayessa dicono di aver chiesto, da qui in poi dovrai cavartela da te. Buona fortuna, {class}.", "Temo che la nostra situazione sia appena diventata ancora più disperata.", "Ho mandato alcuni dei maghi che ci restano ad assicurarsi che anche Valennia e le sue forze riuscissero a fuggire. A quest'ora dovrebbe riposare nella residenza dell'alto anziano Shadowsong.\n\nAnsirem è dovuto tornare su Azeroth, ma prima di partire abbiamo discusso insieme delle prossime mosse dell'Alto Ordine. Siamo sopravvissuti a questa giornata, ma ora Zephras è pericolosamente vulnerabile e dobbiamo prepararci a ciò che verrà.", 0x90290d9d, 0x21f66bcc, 0xcf4192f2, 0x2b65e1b1, 0x2047cb19, "....." },
  [93836] = { "Il destino di Zephras", "Parla con Talaanis Shadowsong a Valanaar.", "Muln mi ha raccontato molto dei signori elementali, e temo che abbiamo buone ragioni per temere Al'Akir. Ora che le protezioni che nascondevano Zephras al suo sguardo sono cadute, siamo del tutto indifesi. Se decidesse di attaccarci, non avremmo alcuna possibilità contro di lui, qui nel suo stesso dominio.\n\nL'alto anziano Shadowsong deve sapere in che pericolo ci troviamo e, soprattutto, quali sono le nostre intenzioni per la nostra missione su Azeroth. Troveremo il modo di salvare la nostra casa. Lo giuro.", nil, "<Talaanis Shadowsong ascolta con attenzione mentre gli racconti ciò che è accaduto sopra il ⟦Shrine of Akir=Sacrario di Akir⟧ e il piano di Ayessa di lasciare l'isola di Zephras.>\n\nDevo rifletterci ancora, ma guardando il lato positivo, ci siamo liberati di Lorthuna e abbiamo privato il culto della sua guida. La nostra casa non è ancora stata invasa e, sulla scala del tempo degli dei elementali, potrebbero passare anni... perfino decenni, prima che Al'Akir si degni di rivolgere la sua attenzione a noi.\n\nOra c'è molto da temere, ma anche molto da festeggiare.", 0x6d3ea2fe, 0x4440ff8a, 0x7c6d6603, nil, 0xa70add28, "...m." },
  [93848] = { "Un lavoro ben fatto", "Torna da Ketharas e informalo di ciò che è accaduto alla Vetta dell'Eternità.", "La magia che Ketharas è riuscito a creare per contrastare questa minaccia è stata vitale per questa vittoria. I nostri druidi dovrebbero poterla replicare e usarla per dissolvere su larga scala le protezioni che potenziano il Patto di Spinanera.\n\nDovresti tornare da Ketharas e informarlo di quanto è accaduto qui. Digli che ha il ringraziamento dei Guardiani di Hyjal e del ⟦Cenarion Circle=Circolo Cenariano⟧. Dovrebbe sapere che sarà sempre il benvenuto tra noi, se desiderasse un posto accanto ai suoi simili druidi.", nil, nil, 0x250ba072, 0x11111364, 0x3ed9c37b, nil, nil, "...mm" },
  [93862] = { "Restituzione della cassa", nil, nil, nil, nil, 0xeb410c2b, nil, nil, nil, nil, ".mmmm" },
  [93925] = { "Perline per Brerufa", nil, nil, nil, nil, 0xcdfc3bdc, nil, nil, nil, nil, ".mmmm" },
  [93926] = { "La vedetta occidentale", "Trova il pacificatore Vaaniel alla torre di guardia occidentale.", "Qualunque sia il motivo per cui il culto attacca la torre, non vale la vita della nostra gente.\n\nVorrei che andassi a sud-ovest a controllare quella torre di guardia per noi. Trova i Pacificatori che sono lì e di' loro di tornare al villaggio. Tenere quella torre non vale le vite che costerebbe, e preferisco concentrare qui i difensori che abbiamo per proteggere i nostri cittadini.\n\nIl comando è del pacificatore Vaaniel: digli di tornare qui il prima possibile. Sbrigati!", nil, "<Il corpo è piuttosto fresco: è evidente che è stato ucciso da poco. A giudicare dalle ustioni e dai segni di bruciatura sulla pelle di questo pacificatore, è chiaro che è stato ucciso dagli incantatori del culto che comandano le tempeste.>", 0x18869d4a, 0xc19f2264, 0x3e46d2b0, nil, 0x4daf9d77, "...m." },
  [93927] = { "Un'ultima richiesta", "Raccogli il biglietto che hai trovato vicino al pacificatore morto e leggilo per capire come procedere.", "<Mentre esamini il corpo del pacificatore morto, un biglietto insanguinato gli scivola dalle mani. Raccoglierlo e leggerlo potrebbe darti un indizio su come procedere.>", "Che notizie porti dalla vedetta occidentale?", "Dunque sono tutti morti. Che le tempeste maledicano quei bastardi del culto!\n\nSei riuscit<o/a> a eliminare il sacerdote e a fermare i cultisti alla torre, ma confesso che ora sono doppiamente preoccupato per ciò che, a quanto dici, stavano facendo al pilone. Il fatto che avessero con sé una scorta così enorme di pietre del vento mi dice che avevano bisogno di un'energia immensa.\n\nMi chiedo quale sia il loro vero scopo. Profanare il pilone, attaccare il villaggio? A che fine?", 0x96fa8046, 0xf1e8b9e6, 0xc18d4d9f, 0x3a64b789, 0xeb80b8f1, "....." },
  [93928] = { "Di topi e latte", "Procura un biscotto al topo.", "Mi serve un biscotto, capito?\n\nNyeah!", nil, nil, 0x4a4cc954, 0xaadb1f71, 0xe2b329a9, nil, nil, "...mm" },
  [93948] = { "La consegna del sigillo", "Consegna il ⟦Shadowsong Family Signet=Sigillo della Famiglia Cantombroso⟧ a Talaanis Shadowsong a Valanaar.", "Visto che vai comunque a Valanaar, ti prego, porta l'anello con sigillo che hai recuperato dalla torre a Talaanis Shadowsong, a Valanaar.\n\nVorrà riaverlo e, soprattutto, vorrà conoscere la sorte di suo nipote. Talaanis è l'alto anziano dell'isola di Zephras e, cosa ancora più importante, è un brav'uomo molto amato dal popolo, nonostante le difficoltà di questi tempi. Mi addolora pensare a come reagirà a questa notizia. Ti prego, porgigli le mie condoglianze per la sua perdita.", "Che cosa hai da darmi? Oh... oh, no.", "Io... sono molto addolorato di sapere che mio nipote è morto. Ti ringrazio di cuore per aver recuperato questo anello e per avermelo portato.\n\nNon capita spesso che shen'dorei giovani e capaci come te scendano dagli altopiani. Se cerchi lavoro, parla con Valennia Stormfist, la capitana dei Pacificatori qui a Valanaar. Di questi tempi ci serve tutto l'aiuto possibile.", 0x95398690, 0x57f7b4b1, 0xba89a78d, 0x93229de8, 0x0454cabb, "....." },
  [93949] = { "Intercettati", "Uccidi gli Skyhopper a Valanaar finché non avrai eliminato $N1 Enchanted Skyhopper.", "Ci stanno spiando.\n\nNelle pianure è la stagione degli skyhopper, il che significa che quegli insetti molesti sono dappertutto. Uno dei maghi dell'Alto Ordine ha riferito che uno degli insetti uccisi portava addosso un qualche incantamento. Esaminandolo da vicino, sembra una specie di incantesimo d'ascolto.\n\nSospettiamo che il culto usi questi insetti incantati come spie. Va' a sterminarli per noi. Non potrai capire quali sono incantati solo guardandoli, quindi dovrai ucciderli tutti.", nil, "Di sicuro ci sono altre di queste bestiole intorno a Valanaar, ma ogni skyhopper incantato che schiacciamo rende la città un pochino più sicura.", 0xebc83872, 0xf0db79e8, 0x5a7063fe, nil, 0xf7ae869a, "...m." },
  [93951] = { "Un tocco di bellezza", "Raccogli 8 piume di ⟦Hippogryph Down=Piumino d'Ippogrifo⟧ negli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧.", "Gli ippogrifi che si sono stabiliti a sud-ovest del villaggio possono essere una seccatura, ma offrono anche un'occasione piuttosto unica per procurarsi le loro piume. Molti skyborne adorano ornarsi i capelli con piume vivaci, e il piumino di un ippogrifo è straordinariamente vivace e, soprattutto, morbido come la seta.\n\nSe vai da quelle parti, cerca di raccogliere quante più piume cadute puoi intorno ai loro nidi. Ma fa' attenzione: gli ippogrifi selvatici non tollerano gli ospiti.", "Quali cose meravigliose mi hai portato?", "Raccogliere piume per i capelli potrebbe sembrare una frivolezza un po' vanitosa. Eppure, anche in tempi come questi, bisogna abbracciare il più possibile le piccole gioie.\n\nSe una sola cosa che creo porta gioia a qualcuno, per me è una buona giornata. Grazie per avermele portate e per avermi aiutato a portare un po' di gioia a Zephras.", 0xfb24871b, 0xf83626f8, 0x2b37a842, 0x1bd026f8, 0x6c68b48e, "....." },
  [93952] = { "Equilibrio attraverso la forza", "Sconfiggi $N1 Guardiano della Tana Legnomorto e torna da Brerufa.", "Pelledura poggia su radici deboli. I Legnomorto artigliano la nostra terra, ogni giorno il loro marciume scava più a fondo, affonda ancora. Non possiamo resistere da soli.\n\nLe guardie della Tana Legnomorto sono il grosso della loro forza. Se cerchi la nostra fiducia, abbatti chi insozza il bosco. Quando i loro Guardiani cadranno, il resto della tribù si indebolirà. Pareggiamo le probabilità.\n\nAbbattili, per l'equilibrio, e aiuta a mantenere intera Hyjal.", nil, nil, 0x40ef28a0, 0x57931f97, 0xa9eeb288, nil, nil, "...mm" },
  [93958] = { "Il santuario interno", "Parla con Valennia Stormfist nel santuario interno del ⟦Shrine of Akir=Sacrario di Akir⟧.", "Le forze di Valennia hanno appena fatto breccia nel santuario interno. All'inizio là dentro si combatteva duramente, ma ora è calato un silenzio... inquietante. Entra e fa' del tuo meglio per ricongiungerti con Valennia e le sue forze... se ne è rimasto qualcuno.\n\nIo resto qui a guardarti le spalle.", nil, "<Valennia sembra gravemente ferita.>", 0x757fc20c, 0xb9c9ad7e, 0xfe6de4be, nil, 0x3a2cf55d, "...m." },
  [93963] = { "Alla scoperta dell'⟦Alliance=Alleanza⟧", "Parla con Randal Emerson nel Castello di ⟦Stormwind=Roccavento⟧ per ricevere altre istruzioni. Segui le istruzioni ricevute per trovare re Magni Barbabronzea, il gran meccanista Meccatork e ⟦Tyrande Whisperwind=Tyrande Soffiabrezza⟧ e parlare con loro.", "⟦Stormwind=Roccavento⟧, ⟦Ironforge=Forgiardente⟧ e Darnassus hanno tutte popoli e culture unici. Come ospite dell'⟦Alliance=Alleanza⟧ qui su Azeroth, dovresti prenderti un po' di tempo per visitare una dopo l'altra tutte le nostre capitali.\n\nParla con Randal Emerson nell'anticamera meridionale: ti darà le indicazioni per cominciare.", nil, "Ah, sei <tornato/tornata>.\n\nSpero che le tue avventure ti abbiano dato un'idea della grandezza e delle meraviglie del nostro mondo. So che deve sembrarti travolgente, ma se vuoi aiutare la tua gente, devi essere <pronto/pronta> a tutto ciò che potrebbe capitarti mentre sei su Azeroth.\n\nMentre aspetti che il tuo ordine si stabilisca a Dalaran, ti suggerisco di rivolgere la tua attenzione alle terre intorno a ⟦Stormwind=Roccavento⟧. Le ⟦Westfall=Marche Occidentali⟧, in particolare, hanno sempre bisogno di altri avventurieri forti che le aiutino, se sei <disposto/disposta> a farlo.", 0xb5c2bf15, 0x80cbe7b7, 0x7db457d1, nil, 0xd5e8b7c2, "...m." },
  [93971] = { "Rapporto di Ricognizione di Farholde", "Porta il rapporto a Krom'rosh a Rog'mar.", "<Il rapporto è sigillato con il sigillo di Farholde. Queste informazioni potrebbero interessare a Krom'rosh a Rog'mar.>", nil, nil, 0xd11ff624, 0xbf57cd76, 0x1574b004, nil, nil, "...mm" },
  [93976] = { "Il mercante goblin", "Consegna la lama al conoscente di Kreza Spinascura al molo a est di Rog'mar.", "Mentre Gur'dok e io continuiamo il nostro lavoro, abbiamo forgiato una lama particolare per un amico... forse amico è una parola troppo forte... per un conoscente giù ai moli. Questa persona in particolare è ben nota e ha contatti in tutti i Regni e oltre.\n\nPrendi questa. Quando la consegni, dille che ti mando io. E dille che siamo pari.", nil, nil, 0xee14b2bd, 0xf6d31b37, 0x6e8deb9f, nil, nil, "...mm" },
})
